    'ReportSubmittedByDateHelp'=>'මෙම වාර්තාව මඟින් සියලු අවදානම්, ඉදිරිපත් කළ දිනය අනුව පෙළගස්වා පෙන්වයි',
    'ReportMitigationsByDateHelp'=>'මෙම වාර්තාව මඟින් සැලසුම් කළ සියලු අවම කිරීම්, අවම කිරීමේ දිනය අනුව පෙළගස්වා පෙන්වයි',
    'ReportMgmtReviewsByDateHelp'=>'මෙම වාර්තාව මඟින් සියලු කළමනාකරණ සමාලෝචන, සමාලෝචන දිනය අනුව පෙළගස්වා පෙන්වයි',
    'ReportProjectsAndRisksHelp'=>'මෙම වාර්තාව මඟින් සියලුම ව්‍යාපෘති සහ ඒවාට පවරා ඇති අවදානම් පෙන්වයි',
