    'AllOpenRisksByTeam'=>'කණ්ඩායම අනුව සියලු විවෘත අවදානම්',
    'ReportRiskTeamsHelp'=>'මෙම වාර්තාව මඟින් සියලු කණ්ඩායම් සහ ඒ සෑම එකකටම පවරා ඇති අවදානම් පෙන්වයි',
    'Unassigned'=>'පවරා නැත',
    'AllOpenRisksByTechnology'=>'තාක්ෂණය අනුව සියලුම විවෘත අවදානම්',
    'ReportRiskTechnologiesHelp'=>'මෙම වාර්තාව මඟින් සියලු තාක්ෂණයන් සහ ඒ සෑම එකකටම පවරා ඇති අවදානම් පෙන්වයි',
