    'CheckAllRiskMgmt'=>'සියලුම අවදානම් කළමනාකරණය පරීක්ෂා කරන්න',
    'CheckAllAssetMgmt'=>'සියලුම වත්කම් කළමනාකරණය පරීක්ෂා කරන්න',
    'CheckAllConfigure'=>'සියලු වින්‍යාස කිරීම් පරීක්ෂා කරන්න',
    'MitigationTeam'=>'අවම කිරීමේ කණ්ඩායම',
    'ImportRisks'=>'අවදානම් ආනයනය කරන්න',
    'ImportAssets'=>'වත්කම් ආනයනය කරන්න',
    'AssetValue'=>'වත්කම් වටිනාකම',
    'Register'=>'ලියාපදිංචි වන්න',
    'RegisterSimpleRisk'=>'SimpleRisk ලියාපදිංචි කරන්න',
    'RegistrationText'=>'ලියාපදිංචි කළ SimpleRisk අවස්ථාවන්ට උත්ශ්‍රේණි කිරීම සහ Secure Controls Framework (SCF) අමතර මොඩියුල වෙත ප්‍රවේශය වහාම ලැබේ.  උත්ශ්‍රේණි කිරීමේ අමතර මොඩියුලය මඟින් බොත්තමක් ඔබා ඔබේ SimpleRisk අවස්ථාවේ උපස්ථයක් ගැනීමට සහ එය උත්ශ්‍රේණි කිරීමට හැකියාව ලැබේ.  Secure Controls Framework (SCF) අමතර මොඩියුලය මඟින් SimpleRisk පාලන කාර්යයන් සමඟ ඒකාබද්ධ වූ පොදු පාලන රාමුවක් සපයයි.  SimpleRisk ලියාපදිංචි කිරීමේදී, ඔබේ ලියාපදිංචි තොරතුරු SimpleRisk විසින් සත්කාරකත්වය දරන සේවාදායකයකට යවනු ලැබේ.  ලබා දෙන ලියාපදිංචි තොරතුරු, නව නිකුතු සහ ආරක්ෂක යාවත්කාලීන පිළිබඳව පාරිභෝගිකයන්ට දැනුම් දීමට SimpleRisk විසින් භාවිත කරනු ලැබේ.  SimpleRisk ලියාපදිංචි කිරීමෙන් ඔබ අපගේ අලෙවිකරණ සන්නිවේදනවලට එක් වන නමුත්, මෙම සන්නිවේදනවල ඇති ඉවත් වීමේ සබැඳිය භාවිතයෙන් ඕනෑම වේලාවක ඉවත් විය හැකිය.  SimpleRisk අපගේ පාරිභෝගිකයන්ගේ පෞද්ගලිකත්වයට ගරු කරන අතර, SimpleRisk ලියාපදිංචි කිරීමේ ක්‍රියාවලිය හරහා අපට ලැබෙන තොරතුරු කිසිවිටෙක තෙවන පාර්ශවයකට විකුණනු නොලැබේ.',
