    'UpgradeInstructions'=>'මෙම කොටස උත්ශ්‍රේණි කිරීමේ අමතර මොඩියුලය භාවිත කරයි.  ඔබ සතුව නවතම අනුවාදය ඇති බව විශ්වාස කර ගැනීමට, "යාවත්කාලීන කරන්න" තෝරා, නැවත ලියාපදිංචි වී, මෙම පිටුව නැවත පූරණය කරන්න.',
