    'UpgradeApplication'=>'යෙදුම උත්ශ්‍රේණි කරන්න',
    'UpgradeDatabase'=>'දත්ත සමුදාය උත්ශ්‍රේණි කරන්න',
    'CustomExtras'=>'අභිරුචි අමතර මොඩියුල',
    'CustomExtrasText'=>'සියල්ල නොමිලේ නම් නියමයි නේද?  SimpleRisk මූලික වේදිකාව ඔබේ සියලු අවදානම් කළමනාකරණ අවශ්‍යතා සපුරාලීමට සමත් වේ යැයි බලාපොරොත්තු වෙමු.  නමුත් ඔබට තවත් කාර්යයන් අවශ්‍ය නම්, ඒ සඳහාම අපි "අමතර මොඩියුල" මාලාවක් සංවර්ධනය කර ඇත්තෙමු.',
