    'RiskAddPermissionMessage' => 'ඔබට නව අවදානම් ඉදිරිපත් කිරීමට අවසර නැත. ඔබ ඉදිරිපත් කිරීමට උත්සාහ කරන ඕනෑම අවදානමක් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලකවරයෙකු අමතන්න.',
