    'InvalidRiskID' => 'අවලංගු අවදානම් හැඳුනුම',
    'Success' => 'සාර්ථකයි',
    'RiskUpdatePermissionMessage' => 'අවදානම් වෙනස් කිරීමට ඔබට අවසරය නොමැත. ඔබ වෙනස් කිරීමට උත්සාහ කරන ඕනෑම අවදානමක් සටහන් නොවනු ඇත. මෙම පණිවිඩය ඔබට වැරදීමකින් ලැබුණු බව ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'RiskReviewPermission' => '$risk_level මට්ටමේ අවදානම් සමාලෝචනය කිරීමට ඔබට අවසරයක් නැත. ඔබ ඉදිරිපත් කිරීමට උත්සාහ කරන ඕනෑම සමාලෝචනයක් වාර්තා නොවනු ඇත. මෙම පණිවිඩය ඔබට දෝෂයකින් ලැබුණු බව ඔබට හැඟේ නම්, කරුණාකර පරිපාලකයෙකු අමතන්න.',
