    'mCryptWarning' => 'සංකේතන අමතරය නිසියාකාරව ක්‍රියා කිරීමට "mcrypt" දිගුව ස්ථාපනය කර තිබිය යුතුය. ඉදිරියට යාමට කරුණාකර එය ස්ථාපනය කරන්න.',
