    'RiskLevelTextTop' => 'මම {$risk_name} අවදානම ලෙස සලකන්නේ {$risk_value} ට සමාන හෝ ඊට වැඩි ඕනෑම දෙයකි, එය {$color_select} වර්ණයෙන් නිරූපණය වේ.',
    'RiskLevelTextRest' => 'මම {$risk_name} අවදානම ලෙස සලකන්නේ ඉහත ඒවාට වඩා අඩු නමුත් {$risk_value} ට සමාන හෝ ඊට වැඩි දෙයකි, එය {$color_select} වර්ණයෙන් නිරූපණය වේ.',
