    'RiskLevelInvalidFieldParameter' => '\'field\' පරාමිතිය සඳහා සපයන ලද අගය අවලංගුයි.',
    'RiskLevelNonNumericValueParameter' => 'ඇතුළත් කළ අගය සංඛ්‍යාත්මක නොවන අගයකි.',
    'RiskLevelTooLongValueParameter' => 'ඇතුළත් කළ අගය ඉතා දිගු ය.',
