    'ImportAssetGroupNoop' => '"{$asset_group_name}" නම් වත්කම් සමූහය දැනටමත් දත්ත සමුදායේ ඇති නිසා ඒ සඳහා කිසිදු ක්‍රියාවක් අවශ්‍ය නොවේ.',
