    'CacheClearWarning' => 'බොහෝ විට නව SimpleRisk නිකුතු මගින් ඔබේ වෙබ් බ්‍රවුසරය විසින් හැඹිලි කර තිබිය හැකි ශෛලි පත්‍ර (stylesheets), රූප සහ javascript සඳහා යාවත්කාලීන ලබා දේ. උත්ශ්‍රේණි කිරීමෙන් පසු SimpleRisk නිසි ලෙස දිස්වන බව සහතික කර ගැනීමට කරුණාකර ඔබේ බ්‍රවුසර හැඹිලිය හිස් කරන්න.',
    'TestAddHeader' => 'නව පරීක්ෂණයක් එක් කරන්න',
    'TestEditHeader' => 'පරීක්ෂණය යාවත්කාලීන කරන්න',
    'ControlEditHeader' => 'පාලනය යාවත්කාලීන කරන්න',
