    'QuestionnaireResultApprovedSuccessfully' => 'ප්‍රශ්නාවලි ප්‍රතිඵලය සාර්ථකව අනුමත කරන ලදී.',
    'QuestionnaireResultRejectedSuccessfully' => 'ප්‍රශ්නාවලි ප්‍රතිඵලය සාර්ථකව ප්‍රතික්ෂේප කරන ලදී. දැනුම්දීමේ විද්‍යුත් තැපෑල සම්බන්ධතාවට යවන ලදී.',
