    'QuestionnaireResultRejectedAuditLog' => '"{$questionnaire_name}" ප්‍රශ්නාවලියේ ප්‍රතිඵලය ප්‍රතික්ෂේප කර, "{$user_name}" පරිශීලක විසින් "{$reject_comment}" අදහසක් සමඟ නැවත ඇගයීම සඳහා "{$contact_name}" සම්බන්ධතාවට ආපසු යවන ලදී.',
    'PrePopulateWithAnswersFromLastAssessment' => 'අවසන් තක්සේරුවේ පිළිතුරු කල්තියා පුරවන්නද?',
    'QuestionnaireResultCommentAuditLog' => '"{$user_name}" පරිශීලක විසින් "{$questionnaire_name}" ප්‍රශ්නාවලියේ ("{$date}" දින "{$contact_name}" සම්බන්ධතාවට යවන ලද) ප්‍රතිඵලය සඳහා අදහසක් එකතු කරන ලදී.',
    'QuestionnaireSentAuditLog' => '"{$questionnaire_name}" ප්‍රශ්නාවලිය "{$user_name}" පරිශීලක විසින් "{$contact_name}" සම්බන්ධතාවට යවන ලදී.',
