    'JiraInstanceURLIsRequired' => 'ජිරා ස්ථාපනයේ URL අවශ්‍යයි!',
    'JiraUserEmailIsRequired' => 'ජිරා පරිශීලකයාගේ විද්‍යුත් තැපෑල අවශ්‍යයි!',
    'JiraUserAPIKeyIsRequired' => 'ජිරා පරිශීලකයාගේ API යතුර අවශ්‍යයි!',
    'JiraInstanceURLIsInvalid' => 'ජිරා ස්ථාපනයේ URL අවලංගුයි, නැතහොත් ජිරා ස්ථාපනය ක්‍රියා විරහිතයි!',
    'JiraServerInfoNotAccessible' => 'ජිරා ස්ථාපනයේ සේවාදායක තොරතුරු අන්ත ලක්ෂ්‍යයට ප්‍රවේශ විය නොහැක, සේවාදායකය වෙබ්හුක් සඳහා සහාය දක්වන්නේ දැයි තීරණය කළ නොහැක.',
    'JiraServerInfoInvalidOrMissingBuildNumber' => 'ජිරා ස්ථාපනයේ බිල්ඩ් අංකය අවලංගුයි, නැතහොත් අස්ථානගතයි, සේවාදායකය වෙබ්හුක් සඳහා සහාය දක්වන්නේ දැයි තීරණය කළ නොහැක.',
    'JiraWebhookNotSupported' => 'වින්‍යාස කර ඇති ජිරා ස්ථාපනය වෙබ්හුක් සඳහා සහාය නොදක්වයි. වෙබ්හුක් සඳහා සහාය දක්වන අවම අනුවාදය 5.2 (බිල්ඩ් අංකය 810+) වේ.',
    'JiraWebhookNotSupportedOnHttp' => 'මෙම අමතර දෙය භාවිත කිරීමට ඔබේ SimpleRisk ස්ථාපනය https මත ක්‍රියාත්මක කළ යුතුය.',
    'JiraConnectionSettingsWarning' => 'ඔබගේ සම්බන්ධතා සැකසුම් අවලංගුය. සමමුහුර්තකරණය සහ සමමුහුර්තකරණ සැකසුම් වලට ප්‍රවේශ වීම අක්‍රීය කර ඇත.',
    'JiraConnectionSettingsSuccess' => 'ඔබගේ සම්බන්ධතා සැකසුම් වලංගු වේ. සමමුහුර්තකරණය සක්‍රීය කර ඇත.',
    'JiraWebhookSetupFailed' => 'වෙබ්හුක් සැකසීම අසාර්ථක විය. කරුණාකර ඔබගේ සම්බන්ධතා සැකසුම් පරීක්ෂා කරන්න.',
    'JiraWebhookSetupSuccess' => 'වෙබ්හුක් සාර්ථකව සකසන ලදී.',

    'JiraProjectSynchronizationSettings' => 'ව්‍යාපෘති සමමුහුර්ත සැකසුම්',
    'JiraFailedGetIssueTypes' => 'නිකුතු වර්ග ලබා ගැනීම අසාර්ථක විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraFailedGetStatuses' => 'පවතින තත්ත්වයන් ලබා ගැනීම අසාර්ථක විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraCreateIssueOnNewRisk' => 'අවදානමක් නිර්මාණය කරන ලදී විට SimpleRisk හට නව ජිරා නිකුතු නිර්මාණය කිරීමට ඉඩ දෙන්න.',
