    'JiraCreateRiskOnNewIssue' => 'නව ජිරා නිකුතුවක් අනාවරණය වූ විට SimpleRisk හට නව අවදානමක් නිර්මාණය කිරීමට ඉඩ දෙන්න.',
    'JiraScanProjectsForNewIssues' => 'ව්‍යාපෘති පරිලෝකනය කරන්න',
