    'JiraGeneralSynchronizationSettings' => 'සාමාන්‍ය සමමුහුර්තකරණ සැකසුම්',
    
    'JiraSynchronizationConflict' => 'ගැටුම',
    'JiraSynchronizationConflictDescription' => 'ගැටෙන ක්ෂේත්‍ර අගයන් සඳහා අවදානමේ අනුවාදය හෝ ජිරා නිකුතුවේ අනුවාදය භාවිත කළ යුතු දැයි තෝරන්න. ජිරා නිකුතුවක් අවදානමකට පවරා ඇති පසු පළමු සමමුහුර්තකරණයටද එම තර්කයම අදාළ වේ.',
    'JiraUseRiskValueOnConflict' => 'අවදානමේ අගය භාවිත කරන්න (පෙරනිමිය)',
    'JiraUseIssueValueOnConflict' => 'ජිරා නිකුතුවේ අගය භාවිත කරන්න',

    'JiraSynchronizationFields' => 'ක්ෂේත්‍ර',
    'JiraSynchronizeStatus' => '"තත්ත්වය" සමමුහුර්ත කිරීම සක්‍රීය කරන්න',
    'JiraSynchronizeStatusSelectionInstructions' => 'කරුණාකර ඔබගේ ව්‍යාපෘතිවල වැඩ ප්‍රවාහවල භාවිත වන ඕනෑම තත්ත්වයකින් නිදහසේ මාරු විය හැකි සහ ඔබගේ සියලුම ව්‍යාපෘති සඳහා ලබා ගත හැකි තත්ත්වයක් තෝරන්න.',
