    'AssetSiteLocation'=>'වත්කම් අඩවිය / ස්ථානය',
    'ActivatingSCFMessage' => 'ආරක්ෂිත පාලන රාමුව (SCF) ස්ථාපනය කිරීම.\n\nමෙය සම්පූර්ණ කිරීමට පැයක් දක්වා ගත විය හැකිය, එය පද්ධති ක්‍රියාකාරිත්වය සහ තෝරාගත් රාමු ගණන මත රඳා පවතී.\n\nපසුබිමේ සකසන අතරතුර ඔබට මෙම පිටුවෙන් ඉවතට යා හැක.',
    'DeactivatingSCFMessage' => 'ආරක්ෂිත පාලන රාමුව (SCF) අස්ථාපනය කිරීම.\n\nමෙය සම්පූර්ණ කිරීමට පැයක් දක්වා ගත විය හැකිය, එය පද්ධති ක්‍රියාකාරිත්වය සහ තෝරාගත් රාමු ගණන මත රඳා පවතී.\n\nපසුබිමේ සකසන අතරතුර ඔබට මෙම පිටුවෙන් ඉවතට යා හැක.',
    'UpdatingSCFMessage' => 'Secure Controls Framework (SCF) රාමුව යාවත්කාලීන කරමින්.\\n\\nපද්ධතියේ ක්‍රියාකාරිත්වය සහ තෝරාගත් රාමු ගණන අනුව මෙය සම්පූර්ණ වීමට පැයක් දක්වා ගත විය හැක.\\n\\nපසුබිමේ සැකසෙන අතරතුර ඔබට මෙම පිටුවෙන් ඉවත් විය හැක.',
