    'Admin' => 'පරිපාලක',
    'AdminRoleDescription' => 'මෙම අවසරය SimpleRisk හි වින්‍යාසයන්ට ප්‍රවේශය ලබා දෙයි. මෙම අවසරය ඇති පරිශීලකයෙකු පද්ධතිය මත ප්‍රායෝගිකව පරිපාලක පරිශීලකයෙකි. ඔවුන්ට "වින්‍යාසගත කරන්න" මෙනුවේ ඇති සියලුම මෙනු වෙනස් කළ හැක. මෙමගින් Extras සක්‍රීය කිරීමට සහ අක්‍රීය කිරීමට, ඒවායේ වින්‍යාස වෙනස් කිරීමට ද ඉඩ ලැබේ. මෙම අවසරය ලබා දිය යුත්තේ එය නිරපේක්ෂවම අවශ්‍ය අයට පමණි. පරිශීලකයෙකුට මෙම අවසරයට ප්‍රවේශය ලැබුණු පසු, ඔවුන්ට අනෙකුත් පරිශීලක ගිණුම් ද සංස්කරණය කළ හැක.',
    'GrantAdmin' => 'පරිපාලක අවසරය ලබා දෙන්න',
    'RemoveAdmin' => 'පරිපාලක අවසරය ඉවත් කරන්න',
    'WouldYouLikeSimpleRiskToAutomaticallyGenerate' => 'තෝරාගත් රාමු සහ පාලන මත පදනම්ව SimpleRisk විසින් ප්‍රශ්නාවලි සැකිල්ලක් ස්වයංක්‍රීයව ජනනය කිරීමට ඔබට අවශ්‍යද?',
    'GenerateStandardQuestionnaireTemplate' => 'සම්මත ප්‍රශ්නාවලි සැකිල්ලක් ජනනය කරන්න',
    'GenerateMaturityQuestionnaireTemplate' => 'පරිණතභාවය පිළිබඳ ප්‍රශ්නාවලි සැකිල්ලක් ජනනය කරන්න',
    'LicenseCheckFailed' => 'ඔබගේ SimpleRisk Extras එකක් හෝ කිහිපයක් බලපත්‍ර පරීක්ෂාවේදී අසාර්ථක වී ඇති අතර, ඉදිරි දින 30 ඇතුළත අක්‍රීය කිරීමට හෝ මකා දැමීමට ඉඩ ඇත. ඔබගේ බලපත්‍රය අලුත් කිරීම සඳහා කරුණාකර වහාම සහාය අමතන්න.',
