    'JiraProjectForNewIssueIsInvalid' => 'නිශ්චිත හැඳුනුම් අංකය සහිත ව්‍යාපෘතියක් සොයාගත නොහැකි විය!',
    'JiraIssueTypeForNewIssueIsRequired' => 'ජිරා නිකුතු වර්ගය අවශ්‍ය වේ!',
    'JiraFailedGetProjects' => 'පවතින ව්‍යාපෘති ලබා ගැනීම අසාර්ථක විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraProjectOrIssueTypeForNewIssueIsNotValid' => 'සපයා ඇති ජිරා ව්‍යාපෘතිය හෝ නිකුතු වර්ගය වලංගු නොවේ.',
    'JiraSuccessfullyCreatedIssue' => 'ජිරා නිකුතුවක් ({$key}) සාර්ථකව නිර්මාණය කරන ලදී.',
    'JiraFailedToCreateIssue' => 'ජිරා නිකුතුව නිර්මාණය කිරීම අසාර්ථක විය! කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'JiraPopulateDescriptionWith' => 'විස්තරය පිරවීමට භාවිත කරන්න',
