    'JiraUserAPIKeyInstructions' => 'ජිරා කෝර් අවස්ථා සඳහා ඔබ ජිරා පරිශීලකයාගේ මුරපදය සඳහන් කළ යුතුය',
    'ActivatingSCFMappingMessage' => 'Github වෙතින් SCF සිතියම්ගත කිරීම ස්ථාපනය කරමින් පවතී. මෙය සම්පූර්ණ වීමට මිනිත්තු කිහිපයක් ගත විය හැක.',
    'DeactivatingSCFMappingMessage' => 'SCF සිතියම්ගත කිරීම අස්ථාපනය කරමින්.',
