    'EditThreat' => 'තර්ජනය සංස්කරණය කරන්න',
    'AreYouSureYouWantToDeleteThisThreatCatalogItem' => 'මෙම තර්ජන නාමාවලි අයිතමය මකන්නට ඔබට විශ්වාසද?',
    'Back' => 'ආපසු',
    'UnableToCommunicateWithTheSimpleRiskServer' => 'SimpleRisk සේවාදායකය සමඟ සන්නිවේදනය කළ නොහැක',
    'Fields' => 'ක්ෂේත්‍ර',
    'TemplateGroup' => 'සැකිලි කණ්ඩායම',
    'AddTemplateGroup' => 'සැකිලි කණ්ඩායම එක් කරන්න',
    'UpdateTemplateGroup' => 'සැකිලි සමූහය යාවත්කාලීන කරන්න',
    'AreYouSureYouWantToDeleteThisTemplateGroup' => 'මෙම සැකිලි කණ්ඩායම මකන්නට ඔබට විශ්වාසද?',
    'CantDeleteDefaultTemplateGroup' => 'ඔබට පෙරනිමි සැකිලි කණ්ඩායම මැකිය නොහැක.',
    'IncidentAddPermissionMessage' => 'නව සිදුවීම් ඉදිරිපත් කිරීමට ඔබට අවසරයක් නොමැත. ඔබ ඉදිරිපත් කිරීමට උත්සාහ කරන ඕනෑම සිදුවීමක් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය ලැබී ඇත්තේ දෝෂයකින් යැයි සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentUpdatePermissionMessage' => 'සිදුවීම් වෙනස් කිරීමට ඔබට අවසරයක් නොමැත. ඔබ වෙනස් කිරීමට උත්සාහ කරන ඕනෑම සිදුවීමක් වාර්තා නොකෙරේ. ඔබට මෙම පණිවිඩය ලැබී ඇත්තේ දෝෂයකින් යැයි සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentPreparationPermissionMessage' => 'සිද්ධි සූදානම් කිරීමේ අයිතම තෝරා ගැනීමට ඔබට අවසරය නොමැත.  ඔබ තෝරා ගැනීමට උත්සාහ කරන ඕනෑම අයිතමයක් සටහන් නොවනු ඇත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentPlaybookSelectPermissionMessage' => 'සීමා කිරීම, තුරන් කිරීම සහ ප්‍රතිසාධන පියවර තීරණය කිරීම සඳහා සිදුවීම් ප්‍රතිචාර මාර්ගෝපදේශයක් තෝරා ගැනීමට ඔබට අවසර නැත. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලකවරයෙකු අමතන්න.',
    'IncidentResponseSelectPermissionMessage' => 'ඔබට සීමා කිරීම, මුලිනුපුටා දැමීම සහ ප්‍රතිසාධන පියවරයන්ගෙන් සිදුවීම් ප්‍රතිචාර ප්ලේබුක් අයිතම තෝරා ගැනීමට අවසර නැත. ඔබ තෝරා ගැනීමට උත්සාහ කරන ඕනෑම අයිතමයක් පටිගත නොකෙරේ. ඔබට මෙම පණිවිඩය වැරදීමකින් ලැබී ඇති බව ඔබට හැඟේ නම් කරුණාකර පරිපාලකවරයෙකු අමතන්න.',
    'IncidentResponseEvidenceAddPermissionMessage' => 'සිද්ධියකට සාක්ෂි එක් කිරීමට ඔබට අවසරය නොමැත.  එක් කරන ඕනෑම සාක්ෂියක් සටහන් නොවනු ඇත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentResponseEvidenceDeletePermissionMessage' => 'සිද්ධියකින් සාක්ෂි මැකීමට ඔබට අවසරය නොමැත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentResponseNoteAddPermissionMessage' => 'සිද්ධියකට සටහන් එක් කිරීමට ඔබට අවසරය නොමැත.  එක් කරන ඕනෑම සටහනක් සටහන් නොවනු ඇත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentResponseNoteDeletePermissionMessage' => 'සිද්ධියකින් සටහන් මැකීමට ඔබට අවසරය නොමැත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentAddLessonPermissionMessage' => 'සිද්ධියකට පාඩම් එක් කිරීමට ඔබට අවසරය නොමැත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'IncidentRemoveLessonPermissionMessage' => 'උගත් පාඩම් වලින් සිද්ධියක් ඉවත් කිරීමට ඔබට අවසරය නොමැත.  මෙම පණිවිඩය ඔබට ලැබී ඇත්තේ දෝෂයකින් යැයි ඔබ සිතන්නේ නම් කරුණාකර පරිපාලකයෙකු අමතන්න.',
    'TemplateAssignment' => 'සැකිලි පැවරුම',
    'PleaseSelectUser' => 'කරුණාකර පරිශීලකයා තෝරන්න',
    'ProjectStatus' => 'ව්‍යාපෘති තත්ත්වය',
    'SupportPortal' => 'සහාය ද්වාරය',
    'WebSupport' => 'වෙබ් සහාය',
    'EmailSupport' => 'විද්‍යුත් තැපෑල සහාය',
    'PhoneSupport' => 'දුරකථන සහාය',
    'NotificationTemplate' => 'දැනුම්දීම් සැකිල්ල',
    'JiraUpdateDetails' => 'ජිරා යාවත්කාලීන විස්තර',
    'YouNeedToSpecifyTheTemplateNameParameter' => 'ඔබ සැකිලි නාම පරාමිතිය සඳහන් කළ යුතුය!',
    'QuestionsLackingAubjectEdited' => 'විෂයක් නොමැති ප්‍රශ්න, හිස් අවදානම් විෂයක් ඉදිරිපත් කිරීමට උත්සාහ නොකරන පරිදි සංස්කරණය කරන ලදී.',
    'AdminSelfEditWarning' => 'පරිපාලක පරිශීලකයින්ට තමන්ගේම පරිපාලක අවසරය ඉවත් කිරීමට හෝ තමන්ම ප්‍රවේශය අහිමි කරගැනීමට නොහැක.',
    'Value' => 'අගය',
    'ControlDetails' => 'පාලන විස්තර',
    'CannotDeleteLastItem' => 'අවසන් අයිතමය මැකිය නොහැක.',
    'FieldChangeTemplate' => '`{$field_name}` (`{$before}` => `{$after}`)',
    'AuditLog_TestAuditReopen' => 'විගණනය "{$test_audit_name}" (ID: {$test_audit_id}) "{$user_name}" පරිශීලකයා විසින් නැවත විවෘත කරන ලදී.',
    'AuditLog_TestAuditClosed' => '"{$test_audit_name}" විගණනය (ID: {$test_audit_id}) "{$user_name}" පරිශීලකයා විසින් වසා දමන ලදී. වෙනස්කම්: {$changes}.',
    'AuditLog_TestAuditUpdated' => 'විගණනය "{$test_audit_name}"(ID: {$test_audit_id}) පරිශීලක "{$user_name}" විසින් යාවත්කාලීන කරන ලදී. වෙනස්කම්: {$changes}.',
    'AuditLog_TestUpdated' => '"{$test_name}" (ID: {$test_id}) පරීක්ෂණය "{$user_name}" පරිශීලකයා විසින් යාවත්කාලීන කරන ලදී. වෙනස්කම්: {$changes}.',
