    'EnableSSLCertificateCheckExternal' => 'බාහිර වෙබ් අඩවි සඳහා SSL සහතික පරීක්ෂා කිරීම් සක්‍රීය කරන්න',
    'EnableSSLCertificateCheckVM' => 'අවදානම්භාවය කළමනාකරණය සඳහා SSL සහතික පරීක්ෂා කිරීම් සක්‍රීය කරන්න',
    'DuoToopherRemoved' => 'Duo දැන් SimpleRisk මගින් සෘජුවම සහාය නොදක්වයි. ඒ වෙනුවට, අපි සාමාන්‍ය TOTP සත්‍යාපකයකට මාරු වී ඇත. කරුණාකර ඔබේ නව සත්‍යාපකය පහතින් පිහිටුවන්න.',
    'ProtectYourSimpleRiskAccount' => 'ඔබේ SimpleRisk ගිණුම ආරක්ෂා කරගන්න',
    '2FADescription' => 'ද්වි-සාධක සත්‍යාපනය ඔබේ අනන්‍යතාවය සත්‍යාපනය කිරීමට ද්විතීයික උපාංගයක් භාවිතා කරමින් ඔබේ ගිණුමේ ආරක්ෂාව වැඩි කරයි. ඔබේ මුරපදය දැන සිටියත්, ඔබ හැර වෙනත් කිසිවෙකුට ඔබේ ගිණුමට ප්‍රවේශ වීම මෙමගින් වළක්වයි.',
