    'RiskDistributionDescription'=>'ඉහත වට ප්‍රස්තාර මගින් සහජ සහ අවශේෂ අවදානම් දෙකටම විවිධ අවදානම් මට්ටම් අතර අවදානම් ව්‍යාප්තිය පෙන්වීමට උපකාරී වේ.  අපගේ අවදානම් අවම කිරීමේ උත්සාහයන්හි ප්‍රගතිය පෙන්වීමට අපට මෙම වට ප්‍රස්තාර දෙක භාවිත කළ හැක.  අවශේෂ අවදානම් වට ප්‍රස්තාරයේ ඉතා ඉහළ හෝ ඉහළ අවදානම්වල විශාල කොටස් පෙන්වන්නේ නම්, ඔබේ සංවිධානය ඉතා වැඩි අවදානමක් භාරගනිමින් සිටින බවටත් තවදුරටත් අවම කිරීමේ උත්සාහයන් අවශ්‍ය බවටත් සං​කේතයක් විය හැක.',
