    'ArtificialIntelligenceAdditionalContextDescription' => 'පහත තොරතුරු අත්‍යවශ්‍ය නොවේ, නමුත් වඩාත් අර්ථවත් ප්‍රතිඵල ලබා දීමට AI හට අවශ්‍ය අමතර සන්දර්භය ඒවා මගින් සපයයි. ඔබේ සංවිධානයට ගැලපෙන පරිදි ප්‍රතිචාර සකස් කිරීම සඳහා පහත ඇතුළත් කරන සියලුම තොරතුරු විශ්ලේෂණය සඳහා ඔබ වින්‍යාස කර ඇති AI සැපයුම්කරු වෙත යවනු ලැබේ.',
