    'SettingsFileUploadDesc'              => 'විවිධ ගොනු ඇමුණුම් ක්ෂේත්‍ර සඳහා අවසර ලත් ගොනු උඩුගත කිරීමේ වර්ග සහ ප්‍රමාණ සීමාවන්.',
    'SettingsMailDesc'                    => 'පිටතට යන විද්‍යුත් තැපැල් දැනුම්දීම් සඳහා SMTP වින්‍යාසය, ප්‍රවාහනය, සත්කාරකය, සත්‍යාපනය සහ ප්‍රතිචාර-ලිපිනය ඇතුළුව.',
    'SettingsBackupsDesc'                 => 'SimpleRisk දත්ත සමුදා උපස්ථ සඳහා උපස්ථ රඳවා තබා ගැනීම, කාලසටහන සහ බාගත කිරීමේ සබැඳි වින්‍යාස කරන්න.',
    'SettingsSecurityDesc'                => 'සත්‍යාපනය, සැසිය, මුරපද ප්‍රතිපත්තිය, මූලික URL, සහ API ආරක්ෂක සැකසුම්.',
    'SettingsLoggingDesc'                 => 'නිදොස්කරණය සහ විගණන ලොග් කිරීමේ වින්‍යාසය: ලොග් මට්ටම්, රඳවා තබා ගැනීම සහ ලොග් ගොනු පිහිටීම.',
    'HealthCheckDesc'                     => 'පද්ධති තත්ත්වය විනිශ්චය කරන්න: PHP අනුවාදය, දිගු, ගොනු අවසර, දත්ත සමුදාය සම්බන්ධතාව, cron කාලසටහන සහ Extra සක්‍රීය කිරීම්.',
    'AnnouncementsDesc'                   => 'සියලුම පරිශීලකයන්ට දිස්වන බැනර් නිවේදන සකසා කළමනාකරණය කරන්න.',
    'RegisterAndUpgradeDesc'              => 'ඔබගේ SimpleRisk ස්ථාපනය ලියාපදිංචි කරන්න, දායකත්ව යතුරක් ඇතුළත් කරන්න හෝ අලුත් කරන්න, සහ එක්-ක්ලික් Core/Extra උත්ශ්‍රේණි කිරීම් ක්‍රියාත්මක කරන්න.',
    'QueueMonitorDesc'                    => 'පසුබිම් කාර්ය පෝලිම පරීක්ෂා කරන්න: රැඳී සිටින, ක්‍රියාත්මක වන සහ අසාර්ථක කාර්ය.',
    'ExtrasDesc'                          => 'SimpleRisk Extras (ගෙවූ ඇඩෝන) සක්‍රිය කරන්න, අක්‍රිය කරන්න සහ වින්‍යාස කරන්න.',
    'ArtificialIntelligenceExtraDesc'     => 'කෘත්‍රිම බුද්ධි Extra මගින් වැඩිදියුණු කළ අවදානම් විශ්ලේෂණය (FAIR තක්සේරු ඇතුළුව) සහ අභිරුචිකරණය කළ ලේඛන සපයයි.',
    'CustomizationExtraDesc'              => 'අභිරුචිකරණ අමතර විශේෂාංගය මඟින් විවිධ වර්ගයේ ක්ෂේත්‍ර එකතු කිරීමට සහ ඉවත් කිරීමට සහ ගතිකව අභිරුචි පිටු සැකිලි නිර්මාණය කිරීමට හැකියාව ලැබේ.',
    'NotificationExtraDesc'               => 'විද්‍යුත් තැපැල් දැනුම්දීම් Extra මගින් අවදානම් ඉදිරිපත් කළ විට, වෙනස් කළ විට හෝ වෙනත් ක්‍රියාමාර්ගයක් ගත් විට SimpleRisk හට විද්‍යුත් තැපැල් දැනුම්දීම් යැවීමට හැකියාව ලබා දේ. අවදානම් කළමනාකරණ සමාලෝචනයට සූදානම් වූ විට සාමාන්‍ය මතක් කිරීම් යැවීම සඳහා මෙම Extra කාලසටහන්ගත ස්ක්‍රිප්ටයක් ලෙසද එක් කළ හැක. SimpleRisk Core නිෂ්පාදනයේ, මෙම Extra නොමැතිව, මෙවලම තුළින් පිටත කිසිදු දැනුම්දීමක් සන්නිවේදනය නොවේ.',
    'VulnerabilityManagementExtraDesc'    => 'අවදානම්සහගත බව කළමනාකරණ Extra මගින් පාරිභෝගිකයන්ට තම SimpleRisk අවස්ථාව Qualys, Tenable.io හෝ Rapid7 Nexpose/InsightVM සමඟ ඒකාබද්ධ කිරීමට සහ වත්කම් සහ අවදානම්සහගත බව දත්ත දෙකම SimpleRisk වෙත ආනයනය කිරීමට හැකියාව සපයයි. ඉන්පසු, ඔබට ආවරණය කිරීමට අවශ්‍ය අඩවි තෝරාගත හැක, ආනයනය කළ යුතු අවදානම්සහගත බව ලකුණු තීරණය කළ හැක, සහ ඒවා ලුහුබැඳීම සඳහා කුමන අවදානම්සහගත බව අවදානම් බවට පත් කරන්නේදැයි ප්‍රමුඛතා අනුව වර්ග කළ හැක.',
    'IncidentManagementExtraDesc'         => 'සිද්ධි කළමනාකරණ Extra, NIST 800-61 පරිගණක ආරක්ෂක සිද්ධි හැසිරවීමේ මාර්ගෝපදේශය මත පදනම් වන අතර SimpleRisk පද්ධතිය තුළින් සිද්ධි කළමනාකරණ හැකියාවන් සපයයි.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'UI හරහා SimpleRisk පාරිභාෂිතය (අවදානම, වත්කම, රාමුව, ආදිය) නැවත නම් කරන්න.',
    'RiskConfigurationDesc'               => 'අවදානම් ලකුණු කිරීමේ නීති වින්‍යාස කරන්න: මට්ටම්, අවදානම් රුචිය, SLA සීමාවන් සහ සම්භාව්‍ය / දායක අවදානම් සූත්‍ර.',
    'RiskAndThreatCatalogDesc'            => 'පතන ලැයිස්තුවල භාවිතා වන අවදානම් සහ තර්ජන අගයන් නාමාවලිය පවත්වා ගන්න.',
    'AddAndRemoveValuesDesc'              => 'අවදානම් ක්ෂේත්‍ර සඳහා පතන අගයන් කළමනාකරණය කරන්න: ස්ථානය, මූලාශ්‍රය, කාණ්ඩය, කණ්ඩායම, තාක්ෂණය සහ තවත් දේ.',
    'AssetValuationDesc'                  => 'වත්කම් තක්සේරු පරිමාණය සහ වත්කම් තක්සේරු අභිබවා යාම වින්‍යාස කරන්න.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => 'පරිශීලකයන් එක් කරන්න, සංස්කරණය කරන්න, අක්‍රීය කරන්න සහ යළි පිහිටුවන්න; මුරපද ප්‍රතිපත්තිය කළමනාකරණය කරන්න.',
    'RoleManagementDesc'                  => 'භූමිකාවන් සහ එක් එක් භූමිකාව ලබා දෙන අවසරයන් නිර්වචනය කරන්න.',
    'TeamManagementDesc'                  => 'වාර්තා දෘශ්‍යතා පෙරහන් කිරීම සඳහා භාවිතා කරන කණ්ඩායම් නිර්මාණය කර කළමනාකරණය කරන්න.',
    'SeparationExtraDesc'                 => 'කණ්ඩායම්-පාදක වෙන්කිරීමේ Extra මගින් අවදානම බැලීම, අදාළ අවදානම පවරා ඇති කණ්ඩායමේ සාමාජිකයින් වන පරිශීලකයන්ට පමණක් සීමා කරයි. SimpleRisk Core නිෂ්පාදනයේ, මෙම Extra නොමැතිව, සෑම පරිශීලකයෙකුටම සෑම අවදානමක්ම දැකිය හැක.',
    'CustomAuthenticationExtraDesc'       => 'අභිරුචි සත්‍යාපන අමතර මෘදුකාංගය Active Directory සහ SAML සත්‍යාපනය සඳහා සහය සපයයි. SimpleRisk Core නිෂ්පාදනයේ, මෙම අමතර මෘදුකාංගය නොමැතිව, එකම විකල්පය වන්නේ SimpleRisk අනන්‍යතා ගබඩාවේ නව පරිශීලකයින් නිර්මාණය කිරීමයි.',
    'EncryptionExtraDesc'                 => 'සංකේතනය කළ දත්ත සමුදාය Extra මගින් අහඹු AES-256 බිට් සංකේතන යතුරක් ජනනය කර, සංවේදී පෙළ SimpleRisk දත්ත සමුදායට ඇතුළත් කිරීමට පෙර එය සංකේතනය කිරීමට භාවිත කරයි. මෙය SimpleRisk යෙදුම සෘජුවම භාවිත නොකර කිසිවෙකුට දත්ත බැලීමට හෝ වෙනස් කිරීමට නොහැකි වීම වළක්වයි.',
    'OrganizationManagementDesc'          => 'සංවිධාන ධුරාවලි Extra මගින් ඕනෑම කණ්ඩායම් ගණනක් ඇතුළත් විය හැකි බහු ව්‍යාපාර ඒකක නිර්වචනය කිරීමේ හැකියාව ලබා දේ. ඉන්පසු පරිශීලකයන් විවිධ ව්‍යාපාර ඒකක යටතේ එක් හෝ කණ්ඩායම් කිහිපයක් හරහා පැවරිය හැක. මෙය පරිශීලකයෙකුට තමා ආශ්‍රිත නොවන කණ්ඩායම්, පරිශීලකයන් සහ වත්කම් බැලීමට සහ භාවිත කිරීමට ඇති හැකියාවට බලපායි.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => 'අවදානම් තොග වශයෙන් මකන්න. අරපිරිමැස්මෙන් භාවිතා කරන්න - මකාදැමීම් ස්ථිරයි.',
    'AuditTrailDesc'                      => 'පරිශීලක ක්‍රියාවන්හි පද්ධති විගණන ලොගය සොයන්න සහ අපනයනය කරන්න.',
    'ImportExportExtraDesc'               => 'ආනයන-අපනයන Extra මගින් CSV ගොනුවක ක්ෂේත්‍ර SimpleRisk දත්ත සමුදායේ ක්ෂේත්‍ර වෙත සිතියම්ගත කරමින් SimpleRisk වෙත දත්ත ආනයනය කිරීමේ හැකියාව සපයයි. එය තෙවන පාර්ශ්වීය ස්ප්‍රෙඩ්ෂීට් එකකින් විගණන ප්‍රතිඵල, වෙනත් මෙවලමකින් අවදානම්සහගත බව ස්කෑන් ප්‍රතිඵල, ඔබේ CMDB වෙතින් වත්කම් සහ තවත් බොහෝ දේ ආනයනය කිරීමට භාවිත කළ හැක. මෙම Extra මගින් අවදානම්, අවම කිරීම්, සමාලෝචන, හෝ ඒ තුනෙහිම සංයුක්ත වාර්තාවක් ඇතුළත් CSV ගොනු SimpleRisk වෙතින් අපනයනය කිරීමේ හැකියාවද සපයයි.',
    'JiraExtraDesc'                       => 'ජිරා ඒකාබද්ධ කිරීමේ Extra මගින් පරිශීලකයන්ට ජිරා අවස්ථාවක් සමඟ ද්වි-දිශානුගතව ඒකාබද්ධ වීමේ හැකියාව සපයයි. එය අවදානම් ජිරා නිකුතු වෙත සම්බන්ධ කිරීමටත්, ඒවායේ දත්ත, තත්ත්වය සහ අදහස් සමමුහුර්ත කිරීමටත් ඉඩ සලසයි.',
    'APIExtraDesc'                        => 'API Extra මගින් පාරිභෝගිකයන්ට උසස් ස්වයංක්‍රීයකරණයක් ලබා ගැනීමට සහ පවතින යටිතල පහසුකම් උපයෝගී කර ගැනීමට, වෙනත් යෙදුම් සමඟ ස්ක්‍රිප්ට් කළ අන්තර්ක්‍රියා නිර්මාණය කිරීම සඳහා RESTful API එකක් භාවිත කිරීමට ඉඩ සලසයි.',
    'AdvancedSearchExtraDesc'             => "උසස් සෙවුම් අමතර කොටස ඉහළ තීරුවේ සෙවුම් කොටුව අවදානම්, රාමු, පාලන, ලේඛන, ව්‍යතිරේක, පරීක්ෂණ, විගණන, වත්කම් සහ වත්කම් කණ්ඩායම් හරහා එක් සෙවුමක් බවට පත් කරයි, ප්‍රතිඵල හරහා වැඩ කිරීම සඳහා සම්පූර්ණ සෙවුම් පිටුවක් ඇත. එය පරිශීලකයාට දැකීමට අවසර දී ඇති වාර්තා පමණක් පෙන්වයි.",
    'AssessmentsExtraDesc'                => 'අවදානම් තක්සේරු Extra මගින් පරිශීලකයන්ට සම්බන්ධතා නිර්වචනය කිරීමට, ප්‍රශ්න (තර්කනය ඇතුළුව) සෑදීමට, ප්‍රශ්නාවලි සැකිල්ලක් සමඟ ප්‍රශ්න කිහිපයක් එකලස් කිරීමට, ප්‍රශ්නාවලි සාදා ඒවා සම්බන්ධතා වෙත යැවීමට, ප්‍රශ්නාවලි ප්‍රතිඵල බැලීමට, එම ප්‍රතිඵල මත පදනම්ව අවදානම් එක් කිරීමට, කාලයත් සමඟ ප්‍රතිඵල සංසන්දනය කිරීමට, බාහිරව අභිරුචිකරණය කළ තක්සේරු ආනයනය සහ අපනයනය කිරීමට, සහ අවදානම් තක්සේරු විගණන ලුහුබැඳීම සමාලෝචනය කිරීමට හැකියාව සපයයි.',
    'ActiveAssessmentsDesc'               => 'දැනට සිදුවෙමින් පවතින තක්සේරු බලන්න සහ කළමනාකරණය කරන්න.',
    'WorkflowsExtraDesc'                  => 'වැඩ ප්‍රවාහ Extra මගින් SimpleRisk තුළ සිදුවන සිදුවීම්වලට ප්‍රතිචාර වශයෙන් අවදානම් කළමනාකරණ ක්‍රියා ස්වයංක්‍රීය කරන දෘශ්‍ය, සිදුවීම්-ධාවිත වැඩ ප්‍රවාහ එන්ජිමක් සපයයි. අවදානමක් ඉදිරිපත් කිරීම, යාවත්කාලීන කිරීම හෝ සමාලෝචනය කිරීම වැනි වෙනස්කම් මත ක්‍රියාත්මක වන වැඩ ප්‍රවාහ ඔබට සැලසුම් කළ හැක — අනුමැති මාර්ගගත කිරීමට, වැඩ පැවරීමට, සහ අතින් මැදිහත් වීමකින් තොරව ඔබේ ක්‍රියාවලිය ඉදිරියට ගෙන යාමට.',

    // Configure Hub - tile descriptions (frameworks category)
