    'EncryptionMissingLockTablesPrivilege'   => 'SimpleRisk දත්ත සමුදාය පරිශීලකයාට LOCK TABLES වරප්‍රසාදය නොමැත. දත්ත සමුදාය ආරක්ෂිතව සංකේතනය කිරීමට එය අවශ්‍ය වේ. දත්ත සමුදාය පරිපාලකයෙකුට ප්‍රතිචාරයේ ලැබෙන GRANT ප්‍රකාශය ක්‍රියාත්මක කරවා නැවත උත්සාහ කරන්න.',
    'EncryptionMissingLockTablesPrivilegeUi' => 'SimpleRisk දත්ත සමුදා පරිශීලකයාට සංකේතනය සඳහා අවශ්‍ය LOCK TABLES වරප්‍රසාදය නොමැත. දත්ත සමුදා පරිපාලකයෙකු ධාවනය කළ යුත්තේ: GRANT LOCK TABLES ON {$db}.* TO {$user}; ඉන්පසු නැවත උත්සාහ කරන්න.',
    'EncryptionRequiredGrantLabel' => 'අවශ්‍ය GRANT ප්‍රකාශය:',
    'EncryptionActivationAlreadyRunning' => 'සංකේතන සක්‍රිය කිරීමක් දැනටමත් සිදුවෙමින් පවතී. එය සම්පූර්ණ වන තෙක් රැඳී සිටින්න නැතහොත් ප්‍රතිසාධනය කිරීමට උපස්ථයෙන් ප්‍රතිසාධනය භාවිතා කරන්න.',
    'EncryptionActivationEnqueued'           => 'සංකේතන අතිරේක සක්‍රීය කිරීම පෝලිමේ තබා ඇත. දත්ත සමුදාය සංකේතනය වන අතරතුර පරිපාලක UI මඟින් ප්‍රගතිය නිරීක්ෂණය කරනු ඇත.',
    'EncryptionActivationEnqueueFailed'      => 'සංකේතන සක්‍රීය කිරීමේ කාර්යය පෝලිමේ තැබීම අසාර්ථක විය. විස්තර සඳහා නිදොස්කරණ ලොගය පරීක්ෂා කරන්න.',
