    'EncryptionDeactivateCtaHelp'           => 'සංකේතනය කළ සෑම තීරුවක්ම නැවත සරල පෙළට විසංකේතනය කරන්න. දත්ත ඇති දත්ත සමුදායක මෙයට මිනිත්තු කිහිපයක් ගත වේ.',
