    'EncryptionBackupCreatedAt'             => 'නිර්මාණය කරන ලදී',
    'EncryptionBackupSize'                  => 'ප්‍රමාණය',
    'EncryptionBackupOriginalFilename'      => 'ගොනුව',
    'EncryptionBackupDownloadTooltip'       => 'නොබැඳි ගබඩා කිරීම සඳහා මෙම උපස්ථ ගොනුවේ පිටපතක් බාගත කිරීමට ක්ලික් කරන්න.',
    'EncryptionBackupStateRestoring'        => 'දැනට ප්‍රතිසාධනයක් සිදුවෙමින් පවතී.',
    'EncryptionNoBackupAvailable'           => 'පූර්ව-සක්‍රිය කිරීමේ උපස්ථයක් දැනට ගබඩා කර නොමැත. සෑම සක්‍රිය කිරීමකම ආරම්භයේදීම උපස්ථය නිර්මාණය වන අතර පසුව සිදුවන ඕනෑම සක්‍රිය කිරීමකින් හෝ අක්‍රිය කිරීමකින් එය උඩින් ලියනු ලැබේ.',
    'EncryptionRestoreCtaHelp'              => 'වලංගුකරණයේදී ගැටලු හමු වී ඔබට සංකේතනයට පෙර තත්ත්වයට ආපසු යාමට අවශ්‍ය නම් මෙය තෝරන්න.',
    'EncryptionRestoreTitle'                => 'උපස්ථයෙන් ප්‍රතිසාධනය කරන්නද?',
    'EncryptionRestoreBodyWhy'              => 'වඩාත්ම මෑත සක්‍රීය කිරීමේ ආරම්භයේදී ගත් සංකේතනයට පෙර ස්නැප්ෂොට් එකට ආපසු යමින් පවතී. සක්‍රීය කිරීමෙන් පසු වලංගුකරණයේදී ගැටලු හමු වී ඔබට සංකේතනය අත්හැරීමට අවශ්‍ය නම් මෙය තෝරන්න.',
    'EncryptionRestoreBodyWhat'             => 'උපස්ථය නිර්මාණය කිරීමෙන් පසු දත්ත සමුදායට ලියූ සෑම පේළියක්ම — අවදානම්, අවම කිරීම්, විගණන ලොග සටහන් සහ සක්‍රීය කිරීමෙන් පසු කළ අනෙකුත් සියලු වෙනස්කම් ඇතුළුව — ස්ථිරවම අහිමි වේ. ප්‍රතිසාධනයේ කොටසක් ලෙස සංකේතනය කළ දත්ත සමුදාය Extra අක්‍රීය කරනු ලැබේ.',
    'EncryptionDeleteBackupCta'             => 'සංකේතනයට පෙර උපස්ථය මකන්න',
    'EncryptionDeleteBackupCtaHelp'         => 'ඔබේ සංකේතනයෙන් පසු වලංගුකරණය සම්පූර්ණ වූ පසු මෙය තෝරන්න. සංකේතනය සැබවින්ම ආරක්ෂාවක් වන්නේ සංකේතනය නොකළ ස්නැප්ෂොට් එක ඉවත් කිරීමෙනි.',
    'EncryptionDeleteBackupTitle'           => 'සංකේතනයට පෙර උපස්ථය මකන්නද?',
    'EncryptionDeleteBackupBodyWhy'         => 'වඩාත්ම මෑත සක්‍රීය කිරීමේ ආරම්භයේදී ගත් ඔබේ දත්තවල සංකේතනය නොකළ ස්නැප්ෂොට් එක ඉවත් කරමින් පවතී. එය අසීමිත කාලයක් තබා ගැනීම සංකේතනයේ අරමුණ නැති කරයි — දත්ත සමුදායට ප්‍රවේශය ඇති ඕනෑම අයෙකුට සංකේතනයට පෙර පිටපත කියවිය හැක.',
    'EncryptionDeleteBackupBodyWhat'        => 'දත්ත සමුදාය තුළ ඇති උපස්ථය වහාම මකා දමනු ලැබේ. දත්ත සමුදාය සංකේතනයට පෙර තත්ත්වයට ආපසු හැරවීමට උපස්ථයෙන් ප්‍රතිසාධනය කරන්න භාවිතා කිරීමට ඔබට තවදුරටත් නොහැකි වේ. පසුව සංකේතනය සම්බන්ධයෙන් ගැටලු හමු වුවහොත්, ඔබේ එකම ප්‍රතිසාධන මාර්ගය ඔබේ මෙහෙයුම් උපස්ථවලින් නව දත්ත සමුදාය ප්‍රතිසාධනයක් වේ.',
    'EncryptionDeleteBackupError'           => 'උපස්ථය මකා දැමීම අසාර්ථක විය. ඩීබග් ලොගය පරීක්ෂා කර නැවත උත්සාහ කරන්න.',
    'EncryptionModalWhyLabel'               => 'මෙය භාවිතා කරන්නේ ඇයි:',
    'EncryptionModalWhatHappensLabel'       => 'ඊළඟට සිදුවන දේ:',
    'EncryptionFieldsPanelHeading'          => 'සංකේතනය කළ දත්ත සමුදා ක්ෂේත්‍ර',
    'EncryptionFieldsHelp'                  => 'මෙහි ලැයිස්තුගත කර ඇති සෑම තීරුවක්ම නිශ්චලව සංකේතනය කර ගබඩා කර ඇත. අගුළු නිරූපකයේ මෙවලම් ඉඟිය භාවිතා කරන ලද ගුප්ත ලේඛන ඇල්ගොරිතම පෙන්වයි.',
    'EncryptionFieldsTableColumn'           => 'දත්ත සමුදා වගුව',
    'EncryptionFieldsFieldColumn'           => 'දත්ත සමුදා ක්ෂේත්‍රය',
    'EncryptionFieldsEncryptedColumn'       => 'සංකේතනය කළ',
    'EncryptionFieldsNoneFound'             => 'දැනට සංකේතනය කළ ක්ෂේත්‍ර කිසිවක් ලියාපදිංචි කර නොමැත. ක්‍රියාකාරී ස්ථාපනයක මෙය සිදු නොවිය යුතුය — බීජ දත්ත සඳහා encrypted_fields වගුව පරීක්ෂා කරන්න.',
    'EncryptionFieldsLockTooltipPrefix'     => 'සංකේතනය කර ඇත්තේ',
    'EncryptionInactiveRedirect'            => 'සංකේතනය කළ දත්ත සමුදාය Extra ක්‍රියාකාරී නොවේ. එය Configure Hub වෙතින් සක්‍රීය කරන්න.',
    'ContactSupport'                        => 'සහාය අමතන්න',
    'BackupDatabaseFailed' => 'දත්ත සමුදාය උපස්ථ කිරීම අසාර්ථක විය. විස්තර සඳහා කරුණාකර SimpleRisk ලොගය පරීක්ෂා කරන්න.',
    'WindowsNotSupported' => 'SimpleRisk 20260421-001 නිකුතුවේ සිට Windows සඳහා තවදුරටත් සහාය නොදක්වයි. කරුණාකර Linux පදනම් වූ සේවාදායකයකට සංක්‍රමණය වන්න.',
    'WindowsUpgradeHalted' => 'මෙම මෙහෙයුම Windows සේවාදායකයක ක්‍රියාත්මක කළ නොහැක. SimpleRisk 20260421-001 නිකුතුවේ සිට Windows සඳහා තවදුරටත් සහාය නොදක්වයි. කරුණාකර Linux පදනම් වූ සේවාදායකයකට සංක්‍රමණය වන්න.',
    'BundleIntegrityVerificationFailed' => 'බාගත කළ SimpleRisk පැකේජය අඛණ්ඩතා සත්‍යාපනයේදී අසාර්ථක විය. උත්ශ්‍රේණි කිරීම නවත්වා ඇති අතර කිසිදු ගොනුවක් වෙනස් කර නොමැත.',
    'BundleDownloadFailed' => 'SimpleRisk බණ්ඩලය බාගත කළ නොහැකි විය. උත්ශ්‍රේණි කිරීම නවතා දමා ඇති අතර කිසිදු ගොනුවක් වෙනස් කර නොමැත.',
    'MissingOrInvalidTrackingID' => 'ලුහුබැඳීමේ හැඳුනුම්පත අතුරුදහන් හෝ අවලංගුයි.',
    'JiraIntegrationExtra' => 'ජිරා ඒකාබද්ධතා අමතර',
    'IncidentManagementNotifications' => 'සිදුවීම් කළමනාකරණ දැනුම්දීම්',
    'NotificationSettingsUpdated' => 'දැනුම්දීම් සැකසුම් යාවත්කාලීන කරන ලදී.',
    'DefaultBusinessUnit' => 'පෙරනිමි ව්‍යාපාර ඒකකය',
    'TheDefaultBusinessUnitEncompasses' => 'සියලුම කණ්ඩායම් ඇතුළත් වන පෙරනිමි ව්‍යාපාර ඒකකය.',
    'UserGuide' => 'පරිශීලක මාර්ගෝපදේශය',
    'AdministratorGuide' => 'පරිපාලක මාර්ගෝපදේශය',
    'DecryptionFailureToast' => 'සංකේතනය කළ ක්ෂේත්‍ර එකක් හෝ කිහිපයක් විසංකේතනය කළ නොහැකි විය. ඒවා හිස්ව පෙන්වයි. විස්තර සඳහා පද්ධති ලොග පරීක්ෂා කරන්න.',
    'EncryptionFailureToast' => 'ක්ෂේත්‍රයක් සංකේතනය කළ නොහැකි වූ අතර ගබඩා කර නොමැත. විස්තර සඳහා පද්ධති ලොග් පරීක්ෂා කරන්න.',
    'EnableAPIv1Endpoints' => 'API v1 අන්ත ලක්ෂ්‍ය සක්‍රීය කරන්න (ඉවත් කිරීමට නියමිත)',
    'EnableAPIv1EndpointsHelp' => 'API v1 ඉවත් කිරීමට නියමිතයි. එය අවශ්‍ය ඒකාබද්ධතාවයක් නොමැති නම් අක්‍රීයව තබන්න. /api/v2/ මෙම සැකසුමෙන් බලපාන්නේ නැති අතර සැමවිටම ලබා ගත හැක.',
    'AllowAPIKeyInURL' => 'URL හෝ POST ශරීරයේ API යතුර ඉඩ දෙන්න',
    'AllowAPIKeyInURLHelp' => 'ආරක්ෂාව සඳහා, API යතුරු X-API-KEY ඉල්ලීම් ශීර්ෂය තුළ යැවිය යුතුය. අක්‍රිය කළ විට, URL විමසුම් නූලෙහි (?key=) හෝ POST ශරීරයෙහි (key=) යවන ලද යතුරු ප්‍රතික්ෂේප කරනු ලැබේ, මන්ද එම ස්ථාන ප්‍රොක්සි ලොග් සහ බ්‍රව්සර් ඉතිහාසයේ වඩාත් පහසුවෙන් නිරාවරණය වේ. X-API-KEY ශීර්ෂය සැමවිටම පිළිගනු ලැබේ. ශීර්ෂය යැවිය නොහැකි ඒකාබද්ධ කිරීමක් නොමැති නම් අක්‍රිය කර තබන්න.',
    'ArtificialIntelligenceDesc' => 'මෙම SimpleRisk අවස්ථාව සඳහා AI සැපයුම්කරු සම්බන්ධතාවය සහ AI ප්‍රතිචාර පදනම් කරන සන්දර්භ ප්‍රශ්න වින්‍යාස කරන්න.',
