    'LocalRegistrationStateCleared' => 'දේශීය ලියාපදිංචි තත්ත්වය හිස් කර ඇත. නව instance_id එකක් ලබා ගැනීමට /admin/register.php හි නැවත ලියාපදිංචි වන්න.',
    'InstanceInformationUpdated' => 'අවස්ථා තොරතුරු යාවත්කාලීන කරන ලදී.',
    'UpgradeExtraDesc' => 'Upgrade Extra මඟින් ලියාපදිංචි කිරීම සහ උත්ශ්‍රේණි කිරීමේ පිටුවෙන්ම යෙදුම සහ දත්ත සමුදාය උත්ශ්‍රේණි බාගත කර යොදමින් සහ ඔබේ අනෙකුත් Extras ස්ථාපනය කර යාවත්කාලීන කරමින් ඔබේ SimpleRisk අවස්ථාව වත්මන්ව තබාගනී. ගොනු අතින් කළමනාකරණය නොකර නවතම නිකුතුවේ රැඳී සිටීමට හැකි වන පරිදි එය කිසිදු ගාස්තුවකින් තොරව SimpleRisk සමඟ ඇතුළත් කර ඇත.',
    'ExtraInstallDisabledByEnforcement' => 'ඔබේ බලපත්‍ර තත්ත්වය නිසා Extra ස්ථාපනය දැනට අක්‍රිය කර ඇත. ඔබේ පරිපාලක හෝ SimpleRisk සහාය අමතන්න.',
    'LicenseStateUnknownRetryShortly' => 'බලපත්‍ර තොරතුරු තවමත් ලබා ගත නොහැක. කරුණාකර සුළු මොහොතකින් නැවත උත්සාහ කරන්න.',
    'LicenseExpiringSoonTitle' => 'බලපත්‍රය ඉක්මනින් කල් ඉකුත් වේ: {$extra}',
    'LicenseExpiringSoonBody' => 'ඔබේ {$extra} බලපත්‍රය {$date} දින කල් ඉකුත් වේ (දින {$days}ක් ඉතිරිය). ප්‍රවේශය අහිමි වීම වළක්වා ගැනීමට ලියාපදිංචි කිරීම සහ උත්ශ්‍රේණි කිරීම මඟින් එය අලුත් කරන්න.',
    'LicenseExpiredTitle' => 'බලපත්‍රය කල් ඉකුත් විය: {$extra}',
    'LicenseExpiredBody' => 'ඔබේ {$extra} බලපත්‍රය {$date} දින කල් ඉකුත් විය. ප්‍රවේශය ප්‍රතිසාධනය කිරීමට ලියාපදිංචි කිරීම සහ උත්ශ්‍රේණි කිරීම මඟින් එය අලුත් කරන්න.',
