    'LicenseStateAnonymousMessage' => 'මෙම SimpleRisk අවස්ථාව ලියාපදිංචි කර නැත. නොමිලේ Extras පමණක් තිබේ. ගෙවන Extras වෙත ප්‍රවේශ වීමට Configure මෙනුවෙන් ලියාපදිංචි වන්න.',
    'LicenseStateUnknownMessage' => 'SimpleRisk හට බලපත්‍ර සේවාව වෙත ළඟා වීමට නොහැකි විය. ඊළඟ පරීක්ෂාවේදී බලපත්‍ර තත්ත්වය ස්වයංක්‍රීයව නැවුම් වනු ඇත.',
    'ExtraIntegrityCheckFailed' => 'බාගත කළ පැකේජය එහි අඛණ්ඩතා පරීක්ෂාවෙන් අසාර්ථක වූ බැවින් ස්ථාපනය කරන ලද්දේ නැත.',
    'ExtraInstallWriteFailed' => 'extras නාමාවලියට ලිවිය නොහැකි නිසා Extra එක ස්ථාපනය කළ නොහැකි විය.',
    'ExtraInstallExtractFailed' => 'Extra බාගත කරන ලද නමුත් එය ලිපිගොනු විවෘත කර ස්ථාපනය කළ නොහැකි විය. යෙදුම් ලොග පරීක්ෂා කරන්න.',
    'EncryptionPreflightFailed' => 'මූලික DDL අසාර්ථක විය — විස්තර සඳහා නිදොස් කිරීමේ ලොගය බලන්න.',
    'EncryptionActivationFailed' => 'මූලික සැකසීමේදී සංකේතන සක්‍රීය කිරීම අසාර්ථක විය. යෙදුම් ලොග පරීක්ෂා කරන්න.',
    'QuestionnaireSentSchedulingOnly' => 'මෙම ප්‍රශ්නාවලිය යවන ලදී. පහත ඇති කාලසටහන් සැකසුම් පමණක් වෙනස් කළ හැක.',
    'AreYouSureYouWantToReopenThisResult' => 'සමාලෝචනය සඳහා මෙම ප්‍රතිඵලය නැවත විවෘත කිරීමට ඔබට විශ්වාසද?',
