    'BypassPendingRisksDescription' => 'අවදානම් සමාලෝචනය සඳහා රඳවා නොතබා, තක්සේරුව සම්පූර්ණ කළ වහාම ඒවා සාදන්න.',
    'AutomaticallySendResultsLabel' => 'ස්වයංක්‍රීයව ප්‍රතිඵල යවන්න',
    'AutomaticallySendResultsDescription' => 'තක්සේරුව සම්පූර්ණ කළ පසු තක්සේරු ප්‍රතිඵල සියලු තක්සේරු සම්බන්ධතා වෙත යවන්න.',
