    'NotifyWhenNotCompleteLabel' => 'සම්පූර්ණ නොවූ විට දැනුම් දෙන්න',
    'NotifyWhenNotCompleteDescription' => 'තක්සේරුව අවසන් නොකළ සම්බන්ධ පුද්ගලයින්ට මතක් කරන්න.',
    'RemindEveryDays' => 'සෑම දින {$day} කටම මතක් කරන්න',
    'ResendAssessmentLabel' => 'තක්සේරුව නැවත යවන්න',
    'ResendAssessmentDescription' => 'නැවත නැවත සිදුවන කාල සටහනකට අනුව තක්සේරුව ස්වයංක්‍රීයව නැවත නිකුත් කරන්න.',
    'ResendEveryDays' => 'සෑම දින {$day} කටම නැවත යවන්න',
    'QuestionnaireSaveBarHint' => '“සුරකින්න සහ යවන්න” මඟින් ප්‍රශ්නාවලිය එහි සම්බන්ධ පුද්ගලයින්ට වහාම නිකුත් කරයි.',
    // Home dashboard — KPI tile labels
    'NewSelfAssessment' => 'නව ස්වයං තක්සේරුව',
    'SelfAssessmentPrereqIntro' => 'ස්වයං තක්සේරු මඟින් ඔබේ සංවිධානය ආරක්ෂිත පාලන රාමුවකට (Secure Controls Framework) එරෙහිව ඇගයීමටත්, අසාර්ථක වන පාලන වලින් අවදානම් ස්වයංක්‍රීයව ජනනය කිරීමටත් ඉඩ සලසයි. පළමුව සැකසුම් පියවර දෙකක් අවශ්‍ය වේ:',
    'RegisterYourInstance' => 'ඔබේ ස්ථාපනය ලියාපදිංචි කරන්න',
    'RegisterYourInstanceHelp' => 'ලියාපදිංචිය මඟින් මෙම ස්ථාපනය SimpleRisk හි බලපත්‍ර සේවාවට සම්බන්ධ කරන අතර, එවිට නොමිලේ ලබාදෙන Extras (SCF ඇතුළුව) බාගත කළ හැක.',
    'InstallTheSCF' => 'ආරක්ෂිත පාලන රාමුව ස්ථාපනය කරන්න',
    'InstallTheSCFHelp' => 'SCF යනු මෙම විශේෂාංගය තක්සේරු කරන රාමු, පාලන ප්‍රශ්න සහ අවදානම් සිතියම්ගත කිරීම් සපයන නොමිලේ අමතර මෘදුකාංගයකි. ස්ථාපනය පසුබිමේ ක්‍රියාත්මක වන අතර මිනිත්තු කිහිපයක් ගත විය හැකිය.',
    'GoToRegistration' => 'ලියාපදිංචිය වෙත යන්න',
    'GoToSCF' => 'ආරක්ෂිත පාලන රාමුව වෙත යන්න',
    'SelfAssessmentEnableTip' => 'විකල්ප: පාලනය > රාමු යටතේ, තක්සේරුවක් ආරම්භ කරන විට කෙටි තෝරාගත් ලැයිස්තුවක් බැලීමට ඔබට නිශ්චිත SCF රාමු සක්‍රීය කළ හැක. සක්‍රීය නොකර වුවද, සම්පූර්ණ SCF නාමාවලියේ ඇති ඕනෑම රාමුවකට එරෙහිව ඔබට තක්සේරු කළ හැක.',
    'ChooseAFramework' => 'තක්සේරු කිරීමට රාමුවක් තෝරන්න',
    'EnabledFrameworks' => 'සක්‍රීය රාමු',
