    'AIProviderURLNotOnAllowlist' => 'මෙම සත්කාරකය AI සැපයුම්කරු SSRF අවසර ලැයිස්තුවේ නොමැත. එය සුරැකීමට පෙර config.php හි $ai_allowed_provider_hosts වෙත එක් කරන්න.',
