    'SoaLegendEvidencePass' => 'මෙම පාලනයේ පරීක්ෂණයක් අවසන් වරට ක්‍රියාත්මක වූ විට සමත් ප්‍රතිඵලයක් වාර්තා කළේය. එය අසල ඇති දිනය එය ක්‍රියාත්මක වූ දිනයයි.',
    'SoaLegendEvidenceFail' => 'මෙම පාලනයේ පරීක්ෂණයක් අවසන් වරට ක්‍රියාත්මක වූ විට අසමත් ප්‍රතිඵලයක් වාර්තා කළේය. ප්‍රතිකාර සැලැස්මක් ඇත්නම්, එය R උපග්‍රන්ථයේ ඇත.',
    'SoaLegendEvidenceInconclusive' => 'මෙම පාලනයේ පරීක්ෂණයක් ක්‍රියාත්මක වූ නමුත් නිගමනයකට එළඹුණේ නැත. මෙම ලේඛනය හඳුනා නොගන්නා ප්‍රතිඵලයක් සඳහාද එම ලකුණම භාවිතා කෙරේ; එවිට ඒ ප්‍රතිඵලයම එය අසල මුද්‍රණය වේ.',
