    'SoaLegendEvidenceDocument' => 'මෙම පාලනය සඳහා සාක්ෂි ලෙස තහවුරු කරන ලද පාලන ලේඛනයක් - එහි ක්‍රියාකාරිත්වයට වඩා එහි සැලසුම. ලේඛනයකට කිසිදු තීන්දුවක් නොමැත, එම නිසා එය හරි ලකුණකින් සලකුණු කර නොමැත.',
