    'ClonedFromControlNotice' => '"{$name}" වෙතින් ක්ලෝන කරන ලදී. පහත ක්ෂේත්‍ර සමාලෝචනය කර, පසුව සුරකින්න.',
    // Task 24 review follow-up: the banner alone left the modal titled "New
