    'ApplicabilityScopeNote' => 'මෙම තීරණය අදාළ වන්නේ "{$framework}" තුළ පමණි. එම පාලනයම වෙනත් රාමුවක් තුළ අදාළව පැවතිය හැකිය.',
    'ApplicabilityAppliesToSelected' => 'මෙම පිටුවේ තෝරාගත් පාලන {$n} සඳහා එය සටහන් කෙරේ.',
    'ApplicabilityAppliesToAllFiltered' => 'වත්මන් පෙරහන්වලට ගැළපෙන, වෙනත් පිටුවල ඇති ඒවා ද ඇතුළුව, සියලු පාලන {$n} සඳහා එය සටහන් කෙරේ.',
    // Per-state hints under the segmented control. The "applicable" one is the
