    'UpgradeStepUpgradingExtras' => 'ස්ථාපනය කර ඇති Extras උත්ශ්‍රේණි කිරීම',
    'UpgradeStepUpdatingUpgradeExtra' => 'උත්ශ්‍රේණි කිරීමේ අමතර කොටස යාවත්කාලීන කිරීම',
