    'UpgradeCorrectionUnknownVersionTitle' => 'වාර්තා කර ඇති දත්ත සමුදාය අනුවාදය සැබෑ නිකුතුවක නමක් නොවේ',
    'UpgradeCorrectionNoRecordedVersion' => 'දත්ත සමුදායේ වාර්තා කළ අනුවාදයක් නැත.',
    'UpgradeCorrectionUnknownVersionFinding' => 'දත්ත සමුදාය \'{$version}\' අනුවාදය වාර්තා කරයි, එය කිසිදු SimpleRisk නිකුතුවක නමක් නොවේ. උත්ශ්‍රේණි කිරීමට එයින් ආරම්භක ලක්ෂ්‍යයක් තෝරාගත නොහැක.',
    'UpgradeCorrectionUnknownVersionGuidance' => 'db_version සැකසුම මෙම දත්ත සමුදායේ ඇත්තටම ඇති ක්‍රමවේදයට අදාළ නිකුතුවට සකසා, ඉන්පසු උත්ශ්‍රේණි කිරීම නැවත ධාවනය කරන්න: UPDATE settings SET value=\'<release>\' WHERE name=\'db_version\'. අගය 2026XXXX-001 වැනි ස්ථාන දරන්නක් නම්, නිවැරදි අගය බොහෝ විට උත්ශ්‍රේණි කිරීම ධාවනය වීමට පෙර ස්ථාපනය කළ නවතම සැබෑ නිකුතුවයි.',
    'UpgradeCorrectionLegacySessionsTitle' => 'උත්ශ්‍රේණි කිරීමේ අක්ෂර කට්ටල පරිවර්තනය sessions වගුවට දරාගත නොහැක',
    'UpgradeCorrectionLegacySessionsFinding' => '`sessions`.`id` යනු MyISAM වගුවක VARCHAR({$width}) වේ. නිකුතුව 20230106-001 සිට සිදුවන පරිදි එය utf8mb4 වෙත පරිවර්තනය කිරීමෙන් MyISAM හි බයිට් 1000 දර්ශක සීමාව ඉක්මවන අතර උත්ශ්‍රේණි කිරීම අසාර්ථක වේ.',
    'UpgradeCorrectionLegacySessionsGuidance' => 'ක්‍රියාකාරී සැසි එකක් හෝ කිහිපයක් අක්ෂර 128 ට වඩා දිග id එකක් භාවිතා කරයි. දැන් තීරුව පටු කිරීමෙන් එම පරිශීලකයින් ඉවත් වන නිසා එය එලෙසම තබන ලදි. එම සැසි කල් ඉකුත් වූ පසු උත්ශ්‍රේණි කිරීම නැවත උත්සාහ කරන්න.',
