    'WeWillEmailAResetTokenToYourAccount' => 'අපි ඔබගේ ගිණුමේ ඇති ලිපිනයට යළි පිහිටුවීමේ ටෝකනයක් විද්‍යුත් තැපෑලෙන් එවන්නෙමු.',
