    'CustomLogo' => 'අභිරුචි ලාංඡනය',
    'CustomLogoHint' => 'PNG, JPG, GIF හෝ WebP, 1 MB සහ 2000x2000 දක්වා. උපරිම 260x64 දක්වා පෙන්වයි, එබැවින් ඉහළ ඝනත්ව තිර සඳහා ආසන්න වශයෙන් 520x128 ලබා දෙන්න. ඉහළ තීරුව සහ ලොගින් පුවරුව අඳුරු වන බැවින්, අඳුරු පසුබිමක කියවිය හැකි ලාංඡනයක් උඩුගත කරන්න. SimpleRisk ලාංඡනයට ආපසු යාමට ලාංඡනය ඉවත් කරන්න.',
