    'DocumentsDeletedTruncated' => 'තෝරාගත් පළමු {$limit} ලේඛන පමණක් මකා දමන ලදී. ඉතිරිය මකා දැමීමට කරුණාකර ක්‍රියාව නැවත කරන්න.',
