    'RestoreTemplateConfirmBodyRisk' => 'මෙය විස්තර, අවම කිරීම සහ සමාලෝචන ටැබ්වල ඇති සෑම ක්ෂේත්‍රයක්ම මෙම සැකිලි කණ්ඩායම සඳහා ඒවායේ පෙරනිමි අගයන් වෙත නැවත සකසයි. අනෙකුත් සැකිලි කණ්ඩායම් වලට බලපෑමක් සිදු නොවේ.',
