    'EaseOfDiscoveryHelp' => 'මෙම තර්ජන නියෝජිත කණ්ඩායමට මෙම අවදානම්සහිත තත්ත්වය (vulnerability) සොයා ගැනීම කෙතරම් පහසුද?
