    'AssetFilterByCategorization' => 'FIPS වර්ගීකරණය {$name} අනුව පෙරන්න',
    'AssetFilteringByCategorization' => 'FIPS වර්ගීකරණය {$name} අනුව පෙරමින්',
    'AssetFilterByBand' => 'භාරිත පරාසය {$name} අනුව පෙරන්න',
    'AssetFilteringByBand' => 'භාරිත පරාසය {$name} අනුව පෙරමින්',
    'AssetScoring' => 'වත්කම් ලකුණු කිරීම',
    'AssetScoringSettingsHint' => 'රහස්‍යභාවය, අඛණ්ඩතාව සහ ලබා ගත හැකි බව සඳහා සෑම වත්කමක්ම අඩු, මධ්‍යස්ථ හෝ ඉහළ ලෙස ශ්‍රේණිගත කර ඇති අතර, රහස්‍යභාවය ඒ වෙනුවට අදාළ නොවේ ලෙස ශ්‍රේණිගත කළ හැකි අතර, එමඟින් එය ප්‍රතිඵල දෙකෙන්ම බැහැර වේ. එහි FIPS වර්ගීකරණය ශ්‍රේණිගත කිරීම් තුනෙන් ඉහළම අගයයි. එහි බර තැබූ ලකුණු මට්ටම් තුනේ අගයන්හි බර තැබූ සාමාන්‍යය වන අතර, කලාප සීමාවන් එම ලකුණු අඩු, මධ්‍යස්ථ හෝ ඉහළ කලාපයක් බවට පත් කරයි. මෙම සැකසුම් වෙනස් කිරීම සෑම වත්කමක්ම වහාම නැවත ලකුණු කරයි.',
    'Weights' => 'බර අගයන්',
    'AssetScoringWeightsHint' => 'භාරිත ලකුණුවලදී සෑම අරමුණක්ම කෙතරම් ගණන් ගනීද යන්න: දශම ස්ථාන දෙකක් දක්වා 0 සිට 100 දක්වා. බර 0 නම් එම අරමුණ බැහැර කෙරේ. අදාළ නොවන රහස්‍යභාවයක් සැමවිටම බැහැර කෙරෙන නිසා අඛණ්ඩතාව සහ ලබාගත හැකිබව දෙකම 0 විය නොහැක.',
    'LevelValues' => 'මට්ටම් අගයන්',
    'AssetScoringLevelValuesHint' => 'භාරිත ලකුණුවලට සෑම ශ්‍රේණිගත කිරීමක්ම දායක වන අගය: 0 ට වැඩි සහ 100 දක්වා, දශම ස්ථාන දෙකක් දක්වා, පහළ < මධ්‍යම < ඉහළ වන පරිදි. පෙරනිමි අගයන් පහළ 1, මධ්‍යම 2 සහ ඉහළ 3 වේ.',
    'BandThresholds' => 'කලාප සීමාවන්',
    'AssetScoringBandThresholdsHint' => 'සීමාවක හෝ ඊට ඉහළින් බරිත ලකුණු එම කලාපයේ ඇති අතර, මධ්‍යස්ථ සීමාවට පහළින් ඇති ලකුණු අඩු වේ. මධ්‍යස්ථ අගය අඩු අගයට ඉහළින් ආරම්භ විය යුතු අතර, ඉහළ අගය මධ්‍යස්ථ අගයට වඩා ඉහළින් ආරම්භ විය යුතු අතර ඉහළ අගයට වඩා වැඩි නොවිය යුතුය.',
    'ModerateStartsAt' => 'මධ්‍යම ආරම්භ වන්නේ',
    'HighStartsAt' => 'ඉහළ ආරම්භ වන්නේ',
    'DefaultScoringForNewAssets' => 'නව වත්කම් සඳහා පෙරනිමි ලකුණු කිරීම',
    'AssetScoringDefaultsHint' => 'වත්කම් පෝරමයේ යමෙක් වත්කමක් එක් කරන විට මෙම ශ්‍රේණිගත කිරීම් කල්තබා තෝරයි. සොයාගැනීම, ආනයනය හෝ API මගින් නිර්මාණය කරන වත්කම්, තමන්ගේම ශ්‍රේණිගත කිරීම් ලබා නොදෙන්නේ නම් ලකුණු නොකළ ලෙස පවතී. මෙය අක්‍රිය කිරීමට සියල්ලම සකසා නැත ලෙස තබන්න.',
    'AssetScoringWeightsInvalid' => 'වත්කම් ලකුණු කිරීමේ බර අගයන් දශම ස්ථාන දෙකකට නොවැඩි 0 සිට 100 දක්වා සංඛ්‍යා විය යුතු අතර, අඛණ්ඩතාව සහ ලබාගත හැකිබව දෙකම 0 විය නොහැක.',
    'AssetScoringValuesInvalid' => 'වත්කම් ලකුණු කිරීමේ මට්ටම් අගයන් 0 ට වැඩි සහ දශම ස්ථාන දෙකකට නොවැඩි 100 දක්වා සංඛ්‍යා විය යුතු අතර, පහළ < මධ්‍යම < ඉහළ විය යුතුය.',
    'AssetScoringThresholdsInvalid' => 'වත්කම් ලකුණු කිරීමේ පරාස සීමාවල දශම ස්ථාන දෙකකට වැඩි නොවිය යුතු අතර, මධ්‍යම පරාසය පහළ අගයට වඩා ඉහළින්ද, ඉහළ පරාසය මධ්‍යමයට වඩා ඉහළින්ද ආරම්භ විය යුතු අතර, ඉහළ පරාසය ඉහළ අගයට වඩා වැඩි නොවිය යුතුය.',
    'AssetScoringDefaultsInvalid' => 'නව වත්කම් සඳහා පෙරනිමි ලකුණු කිරීම එක් එක් අරමුණ ලබා දෙන මට්ටමක් විය යුතුය.',
    'AssetScoringSettingsNotSaved' => 'වත්කම් ලකුණු කිරීමේ සැකසුම් සුරැකිය නොහැකි විය. කිසිවක් වෙනස් කර නැත.',
    'AssetScoringSettingsChangedLog' => '"{$user}" පරිශීලකයා විසින් වත්කම් ලකුණු කිරීමේ සැකසුම් වෙනස් කරන ලදී.',
    'AssetScoringNotSet' => 'සකසා නැත',
    'NotScored' => 'ලකුණු කර නැත',
    'AssetScoringNotScoredHint' => 'මෙම වත්කම ලකුණු කිරීමට අරමුණු තුනටම පිළිතුරු දෙන්න.',
    'ImportAssetScoringValueIgnored' => '"{$asset_name}" වත්කම සඳහා {$objective} අගය "{$value}" වලංගු ශ්‍රේණිගත කිරීමක් නොවන අතර නොසලකා හරින ලදී.',
