    'AssetScoringNoWeightedScore' => 'බර තැබූ ලකුණු නැත',
    'AssetScoringNoWeightedScoreNote' => 'බරිත ලකුණු නොමැත: ගණන් ගන්නා සෑම අරමුණකම බර 0 කි.',
    'AssetScoringUpgradePending' => 'SimpleRisk දත්ත සමුදා උත්ශ්‍රේණි කිරීම ක්‍රියාත්මක වන තුරු වත්කම් ලකුණු කිරීම සුරැකිය නොහැක. කිසිවක් වෙනස් කර නැත.',
    'AssetScoringResultHelpLabel' => '{$result} පැහැදිලි කිරීම',
    'AssetScoringScoreHelp' => 'බර තබන ලද ලකුණු මගින් ශ්‍රේණිගත කිරීම් තුන {$low} සිට {$high} දක්වා එක් අංකයකට මුහු කරයි. සෑම ශ්‍රේණිගත කිරීමක්ම එහි නියම කළ අගය බවට පත් වන අතර, සෑම එකක්ම එහි අරමුණේ බරෙන් ගුණ කෙරේ. ප්‍රතිඵල එකතු කර බරවල මුළු එකතුවෙන් බෙදනු ලැබේ. අදාළ නොවන රහස්‍යභාවය එහි බර සමඟ ඉවත් කෙරේ. නියම කළ අගයන් සහ බර මනාප තුළ වින්‍යාස කෙරේ. ලකුණු පෙන්වීමට පෙර අරමුණු තුනම ශ්‍රේණිගත කළ යුතුය.',
    'AssetScoringCategorizationHelp' => 'FIPS 199 ආරක්ෂක ප්‍රවර්ගීකරණය යනු ඉහළම සලකුණයි: අදාළ වන අරමුණු අතරින් ඉහළම ශ්‍රේණිගත කිරීම. එක් ඉහළ ශ්‍රේණිගත කිරීමක් තිබීමෙන්, අනෙක් ඒවා කුමක් වුවත්, වත්කම ඉහළ වේ. අදාළ නොවේ යන්න නොසලකා හරිනු ලැබේ.',
    'AssetScoringBandHelp' => 'පරාසය මගින් බර තබන ලද ලකුණු අඩු, මධ්‍යස්ථ හෝ ඉහළ පරිමාණයක තබයි. {$moderate} ට අඩු ලකුණු අඩු වේ, {$moderate} සිට {$highAt} දක්වා මධ්‍යස්ථ වේ, {$highAt} හෝ වැඩි නම් ඉහළ වේ. සීමාවන් මනාප තුළ වින්‍යාස කෙරේ.',
