    'AllIntegrityRatings' => 'සියලුම අඛණ්ඩතා ශ්‍රේණිගත කිරීම්',
    'AllAvailabilityRatings' => 'සියලු ලබාගත හැකිබව ශ්‍රේණිගත කිරීම්',
    'AssetFilterByConfidentiality' => 'රහස්‍යභාවය {$name} අනුව පෙරන්න',
