    'AdvancedSearchLockedPitch' => 'එක් කොටුවකින් අවදානමක්, පාලනයක්, ලේඛනයක් හෝ වත්කමක් සොයාගෙන, එයට සම්බන්ධ වාර්තා වෙත පනින්න.',
