    'UserImportRowError' => 'පේළිය {$row}: අනපේක්ෂිත දෝෂයක් නිසා ආනයනය නොකරන ලදී.',
    'UserImportRevealPasswords' => 'තාවකාලික මුරපද පෙන්වන්න',
    'UserImportPasswordsOnce' => 'නව පරිශීලකයින්ගේ තාවකාලික මුරපද එක් වරක් පමණක් පෙන්වා පසුව මකා දමනු ලැබේ. දැන්ම ඒවා පිටපත් කර, එක් එක් පරිශීලකයාට ඔහුගේ/ඇයගේ මුරපදය ආරක්ෂිතව ලබා දෙන්න. සෑම පරිශීලකයෙකුම පළමු පිවිසීමේදී එය වෙනස් කළ යුතුය.',
    'UserImportPasswordsShownOnce' => 'මෙම තාවකාලික මුරපද SimpleRisk වෙතින් මකා දමා ඇති අතර නැවත පෙන්විය නොහැක. දැන්ම ඒවා පිටපත් කරන්න. සෑම පරිශීලකයෙකුම පළමු පිවිසීමේදී තමාගේ මුරපදය වෙනස් කළ යුතුය.',
    'UserImportPasswordsUnavailable' => 'තාවකාලික මුරපද තවදුරටත් පෙන්විය නොහැක. ඒවා පෙන්වන්නේ එක් වරක් පමණි, ආනයනය ආරම්භ කළ පරිපාලකයාට පමණක්, ඒ ආරම්භ කළ බ්‍රවුසර ටැබය තුළ පමණි, සහ ඒවා නැවත පෙන්විය හැකි කිසිවක් SimpleRisk රඳවා නොගනී. පරිශීලකයා සංස්කරණය කිරීමෙන් එක් එක් නව පරිශීලකයා සඳහා නව මුරපදයක් සකසන්න.',
    'UserImportBackgroundNote' => 'මෙම පිටුව ස්වයංක්‍රීයව යාවත්කාලීන වන අතර ඔබ ඉවත් වුවද ආනයනය දිගටම ක්‍රියාත්මක වේ. ප්‍රතිඵලය බැලීමට පිටුව නැවත විවෘත කරන්න.',
    'AuditAdditionalStakeholdersSetOnTest' => 'අමතර පාර්ශ්වකරුවන් පරීක්ෂණය මත සකසා ඇත. ඔවුන් වෙනස් කිරීමට, {$page} යටතේ පරීක්ෂණය සංස්කරණය කරන්න; වෙනස්කම මෙම විගණනයට වහාම බලපායි.',
    'QuestionnaireDraftSomeFilesNotSaved' => 'ඔබගේ පිළිතුරු සුරකින ලදී, නමුත් ඇමුණුම් එකක් හෝ කිහිපයක් ගබඩා කර නොමැත. ගොනුවක් ඉතා විශාල හෝ අවසර නැති වර්ගයක විය හැකිය.',
    'UploadFileTooBigForDatabase' => 'උඩුගත කරන ලද ගොනුව දත්ත සමුදායට ගබඩා කිරීමට නොහැකි තරම් විශාලය. SimpleRisk පරිපාලකයෙකුට MySQL වින්‍යාසයේ ඇති max_allowed_packet සහ innodb_log_file_size අගයන් ඉහළ නැංවිය හැක.',
    'UploadErrorIniSize' => 'උඩුගත කරන ලද ගොනුව php.ini හි upload_max_filesize විධානය ඉක්මවා යයි.',
    'UploadErrorFormSize' => 'උඩුගත කරන ලද ගොනුව HTML පෝරමයේ නිශ්චිතව දක්වා ඇති MAX_FILE_SIZE විධානය ඉක්මවා යයි.',
    'UploadErrorPartial' => 'උඩුගත කරන ලද ගොනුව අර්ධ වශයෙන් පමණක් උඩුගත කර ඇත.',
    'UploadErrorNoFile' => 'ගොනුවක් උඩුගත කර නැත.',
    'UploadErrorNoTmpDir' => 'තාවකාලික ෆෝල්ඩරයක් අතුරුදහන්.',
    'UploadErrorCantWrite' => 'ගොනුව තැටියට ලිවීම අසාර්ථක විය.',
    'UploadErrorExtension' => 'PHP දිගුවක් ගොනු උඩුගත කිරීම නැවැත්වීය.',
    'MaxUploadSizeNeedsInteger' => 'උපරිම උඩුගත කිරීමේ ගොනු ප්‍රමාණය බිංදුවට වඩා වැඩි බයිට් පූර්ණ සංඛ්‍යාවක් විය යුතුය.',
    'MaxUploadSizeUpdated' => 'උපරිම උඩුගත කිරීමේ ගොනු ප්‍රමාණය සාර්ථකව යාවත්කාලීන කරන ලදී.',
    'MaxUploadSizeCapped' => 'සුරකින ලද අගය මෙම සේවාදායකය ඉඩ දෙන අගයට වඩා වැඩිය; එබැවින් PHP සහ MySQL සීමා ඉහළ නංවන තෙක් හෝ මෙම අගය අඩු කරන තෙක් විශාල ගොනු ප්‍රතික්ෂේප කෙරේ. දැනට පිළිගන්නා විශාලතම ගොනුව, බයිට් වලින්:',
    'PleaseEnterAValidEmailAddress' => 'කරුණාකර වලංගු විද්‍යුත් තැපැල් ලිපිනයක් ඇතුළත් කරන්න.',
    'RiskImportedClosedWithoutCloseReason' => 'අවදානම {$risk_id} ("{$subject}") වසා දැමූ තත්ත්වයෙන් ආනයනය කරන ලද නමුත් වසා දැමීමේ හේතුවක් නොමැත, එබැවින් එහි වසා දැමීමේ තොරතුරු අසම්පූර්ණය. ගොනුවට වසා දැමීමේ හේතුවක් එක් කර නැවත ආනයනය කරන්න, නැතහොත් අවදානම් පිටුවෙන් වසා දැමීම සම්පූර්ණ කරන්න.',
    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'HTTP දැඩි ප්‍රවාහන ආරක්ෂාව (HSTS) සබල කරන්න',
    'EnableHSTSHelp' => 'පහත උපරිම කාලය සඳහා SimpleRisk වෙත HTTPS හරහා පමණක් සම්බන්ධ වන ලෙස බ්‍රවුසරවලට දන්වයි. මෙම අඩවියේ HTTPS විශ්වාසදායක ලෙස ක්‍රියා කරන බව තහවුරු වූ පසු පමණක් මෙය සක්‍රීය කරන්න: මෙම ශීර්ෂය දුටු බ්‍රවුසර සාමාන්‍ය HTTP ප්‍රතික්ෂේප කරන අතර, උපරිම කාලය අවසන් වන තෙක් දෝෂ සහිත සහතිකයක් මඟ හැරිය නොහැක. තත්පර 300 වැනි කෙටි උපරිම කාලයකින් ආරම්භ කර, HTTPS සත්‍යාපනය වූ පසු එය ඉහළ නංවන්න.',
    'HSTSMaxAge' => 'HSTS උපරිම කාලය (තත්පර)',
    'HSTSMaxAgeInvalid' => 'HSTS උපරිම කාලය 0 සහ 63072000 අතර තත්පර පූර්ණ සංඛ්‍යාවක් විය යුතුය.',
    'HSTSIncludeSubdomains' => 'සියලුම උප වසම් වලට HSTS යොදන්න',
    'HSTSIncludeSubdomainsHelp' => 'මෙම සත්කාරකයේ සෑම උප වසමකටම HTTPS බලෙන් යොදයි. කිසියම් උප වසමක් සාමාන්‍ය HTTP හරහා සපයන්නේ නම් මෙය අක්‍රීයව තබන්න.',
    'UpgradeNotificationTitle' => 'SimpleRisk උත්ශ්‍රේණි කර ඇත',
    'UpgradeNotificationBody' => 'SimpleRisk අනුවාදය {$version} වෙත උත්ශ්‍රේණි කරන ලදී. වෙනස් වී ඇති දේ දැන ගැනීමට නිකුතු සටහන් බලන්න.',
    'QuestionnaireStaleClientRefresh' => 'ඔබගේ ප්‍රගතිය ස්වයංක්‍රීයව සුරැකීම දිගටම කරගෙන යාමට කරුණාකර මෙම පිටුව නැවුම් කරන්න.',
    'SamlLoginRejectedTitle' => 'පිවිසීම සම්පූර්ණ කළ නොහැකි විය',
    'SamlLoginRejectedMessage' => 'ඔබගේ අනන්‍යතා සැපයුම්කරුගේ ප්‍රතිචාරය පිළිගත නොහැකි විය, එබැවින් ඔබව පුරනය කර නොමැත. පිවිසුම් පිටුවට ආපසු ගොස් නැවත උත්සාහ කරන්න. ගැටලුව දිගටම පවතින්නේ නම්, ඔබගේ SimpleRisk පරිපාලක අමතන්න.',
    'SamlLoginRejectedReference' => 'යොමුව: {$id}',
    'InvalidUserResetToken' => 'අවලංගු පරිශීලක යළි පිහිටුවීමේ ටෝකනය.',
