    'QuestionnaireCompletionNotificationFailed' => 'ප්‍රශ්නාවලිය "{$questionnaire_name}" සඳහා (සම්බන්ධතා "{$contact_name}" විසින් සම්පූර්ණ කරන ලද) සම්පූර්ණ කිරීමේ දැනුම්දීමක් {$role} "{$recipient_name}" ({$recipient_email}) සඳහා පෝලිමේ තැබිය නොහැකි විය.',
