    'QuestionnaireEditRejectedAuditLog' => '"{$name}" යන නම ඇති ප්‍රශ්නාවලියකට "{$user_name}" යන පරිශීලක නාමයෙන් වෙනස්කම් සුරැකීමට ගත් උත්සාහයක් ප්‍රතික්ෂේප කරන ලදී: {$reason}',
    'SoaRemediationNoMitigation' => 'අවම කිරීමක් සැලසුම් කර නැත',
    'SoaLegendNoMitigation' => 'අවදානමකට සම්බන්ධ අසාර්ථක පරීක්ෂණයක්, නමුත් එම අවදානමට තවම අවම කිරීමක් නොමැති බැවින් කිසිදු ප්‍රතිකාර සැලැස්මක් සටහන් කර නැත.',
