    'RestartXSelectedTasksQuestion' => '{$count} තෝරාගත් කාර්යයන් නැවත ආරම්භ කරන්නද?',
    'QueueStopConfirmBody' => 'ක්‍රියාත්මක වෙමින් පවතින පියවර පළමුව අවසන් වේ. තවත් පියවර කිසිවක් ආරම්භ නොවන අතර, පසුව කාර්යය අවලංගු කරන ලද ලෙස පෙන්වයි.',
    'QueueCancelConfirmBody' => 'කාර්යය ක්‍රියාත්මක නොවේ. දැනටමත් අවසන් කර ඇති පියවර අහෝසි නොකෙරේ.',
    'QueueCancelSelectedConfirmBody' => 'පොරොත්තු කාර්ය වහාම අවලංගු වේ. ක්‍රියාත්මක වන කාර්යයක් එහි වත්මන් පියවර අවසන් කර ඉන්පසු නවතී. දැනටමත් අවසන් වූ පියවර ආපසු හරවනු නොලැබේ.',
    'QueueRunNowConfirmBody' => 'කාර්යය ක්ෂණික ප්‍රමුඛතාවයෙන් පෝලිමේ ඉදිරියට ගෙන යන අතර, නැවත උත්සාහ කිරීමේ ඕනෑම පොරොත්තුවක් ඉවත් කෙරේ; එබැවින් ඊළඟ වර්කර් පරීක්ෂණයේදී එය ගනු ලැබේ.',
    'QueueRestartConfirmBody' => '1 වන පියවරෙන් නැවත ආරම්භ වන නව කාර්යයක් පෝලිමට එක් කෙරේ. මුල් කාර්යය ඉතිහාසය ලෙස ලැයිස්තුවේ පවතී.',
    'QueueRestartSelectedConfirmBody' => 'තෝරාගත් සෑම කාර්යයක් සඳහාම 1 වන පියවරෙන් නැවත ආරම්භ වන නව කාර්යයක් පෝලිමට එක් කෙරේ. මුල් කාර්ය ඉතිහාසය ලෙස ලැයිස්තුවේ පවතී.',
    'QueueTaskWillRunAgainWarning' => 'විද්‍යුත් තැපැල් යැවීම වැනි ඕනෑම අතුරු ආචරණයක් ඇතුළුව කාර්යය නැවත ක්‍රියාත්මක වේ.',
    'QueueTasksWillRunAgainWarning' => 'විද්‍යුත් තැපැල් යැවීම වැනි ඕනෑම අතුරු ආචරණයක් ඇතුළුව මෙම කාර්ය නැවත ක්‍රියාත්මක වේ.',
    'QueueTaskWillRunOnNextPassWarning' => 'විද්‍යුත් තැපැල් යැවීම වැනි ඕනෑම අතුරු ආචරණයක් ඇතුළුව කාර්යය ඊළඟ වර්කර් පරීක්ෂණයේදී ක්‍රියාත්මක වේ.',
    'QueueWorkerNotRunningTasksWait' => 'පෝලිම් වර්කර් ක්‍රියාත්මක නොවන නිසා, එය නැවත ආරම්භ වන තෙක් කිසිවක් ක්‍රියාත්මක නොවේ.',
    'XAppliedYSkipped' => '{$applied} ක් යෙදුණි, {$skipped} ක් මඟ හැරුණි.',
    'TaskXRestartedAsTaskY' => '#{$id} කාර්යය #{$new_id} කාර්යය ලෙස නැවත ආරම්භ කරන ලදී.',
    'XSkippedTaskStateChanged' => '{$count} කාර්යය තත්ත්වය වෙනස් වූ නිසා මඟ හැරුණි.',
    'XSkippedTaskNoLongerExists' => 'කාර්යය තවදුරටත් නොපවතින නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedTaskTypeCannotBeCanceled' => 'මෙම කාර්ය වර්ගය අවලංගු කිරීමට හෝ කලින් ක්‍රියාත්මක කිරීමට නොහැක නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedTaskTypeCannotBeRestarted' => 'මෙම කාර්ය වර්ගය නැවත ආරම්භ කිරීමට නොහැක නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedTaskAlreadyRestarted' => 'කාර්යය දැනටමත් නැවත ආරම්භ කර ඇති නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedTaskStillStopping' => 'කාර්යය තවමත් නතර වෙමින් පවතින නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedUnexpectedError' => 'අනපේක්ෂිත දෝෂයක් නිසා {$count} ක් මඟ හැරුණි.',
    'SelectAllXMatchingTasks' => '{$count} ගැළපෙන සියලුම කාර්යයන් තෝරන්න',
    'AllXMatchingTasksSelected' => '{$count} ගැළපෙන සියලුම කාර්යයන් තෝරා ඇත',
    'ChooseAStatusFilterToActOnSelectedTasks' => 'තෝරාගත් කාර්යයන් මත ක්‍රියා කිරීමට තත්ව පෙරහනක් තෝරන්න.',
    'TooManyTasksSelectedSelectAtMostX' => 'කාර්යයන් ඕනෑවට වඩා තෝරාගෙන ඇත. එකවර උපරිම {$max} තෝරන්න.',
    'CompletedAndCanceledTasksDays' => 'සම්පූර්ණ කළ සහ අවලංගු කළ කාර්යයන් (දින)',
    'FailedTasksDays' => 'අසාර්ථක වූ කාර්යයන් (දින)',
    'QueueRetentionHint' => 'මීට වඩා පැරණි අවසන් කළ කාර්ය සහ ඒවායේ පියවර දිනකට වරක් මකා දමනු ලැබේ. පොරොත්තු සහ ධාවනය වන කාර්ය කිසිවිටෙක මකා නොදමයි.',
    'ZeroKeepsTasksForever' => 'කාර්ය සදහටම තබා ගැනීමට 0 ඇතුළු කරන්න.',
    'EnterAWholeNumberFrom0ToX' => '0 සිට {$max} දක්වා පූර්ණ සංඛ්‍යාවක් ඇතුළත් කරන්න.',
    'RetentionSettingsSaved' => 'රඳවා ගැනීමේ සැකසුම් සුරකින ලදී.',
    'RestartedAsTaskX' => 'කාර්යය #{$id} ලෙස නැවත ආරම්භ කරන ලදී',
    'NoTasksMatchAnyMore' => 'තේරීමට ගැලපෙන කාර්යයන් තවදුරටත් නොමැත. ලැයිස්තුව නැවුම් කර ඇත.',
    'RequestMayHaveBeenAppliedCheckTheList' => 'ඉල්ලීම අවසන් වූයේ නැත, එබැවින් එය තවමත් යෙදී තිබිය හැක. නැවත උත්සාහ කිරීමට පෙර නැවුම් කළ ලැයිස්තුව පරීක්ෂා කරන්න.',
    'StepWorkerNotRunningStepsWait' => 'පියවර සේවකයා ධාවනය වන්නේ නැත, එබැවින් එය නැවත ආරම්භ වන තෙක් කාර්ය පියවර ඉදිරියට නොයයි.',
    'WorkerStatusUnknownTasksMayWait' => 'සේවක තත්ත්වය පරීක්ෂා කළ නොහැකි විය, එබැවින් සේවකයෙකු ක්‍රියාත්මක නොවන්නේ නම් කාර්යය රැඳී සිටිය හැක.',
    'CancelThisTaskQuestion' => 'මෙම කාර්යය අවලංගු කරන්නද?',
    'RestartThisTaskQuestion' => 'මෙම කාර්යය නැවත ආරම්භ කරන්නද?',
    // Queue Monitor bulk delete of finished tasks (SR-2408)
    'DeleteTask' => 'කාර්යය මකන්න',
