    'DeleteThisTaskQuestion' => 'මෙම කාර්යය මකන්නද?',
    'DeleteXSelectedTasksQuestion' => 'තෝරාගත් කාර්ය {$count} ක් මකන්නද?',
    'QueueDeleteConfirmBody' => 'කාර්යය සහ එහි පියවර වාර්තා පෝලිමෙන් මකා දමනු ලැබේ.',
    'QueueDeleteSelectedConfirmBody' => 'තෝරාගත් කාර්ය සහ ඒවායේ පියවර වාර්තා පෝලිමෙන් මකා දමනු ලැබේ. SimpleRisk විසින් ඉතිහාසය තබා ගන්නා කාර්ය සහ තවමත් නතර වෙමින් පවතින හෝ පියවරක් ධාවනය වන කාර්ය මඟ හැරේ.',
    'XDeletedYSkipped' => '{$deleted} ක් මකා දමන ලදී, {$skipped} ක් මඟ හැරුණි.',
    'XSkippedTaskTypeCannotBeDeleted' => 'මෙම කාර්ය වර්ගය මැකිය නොහැක නිසා {$count} ක් මඟ හැරුණි.',
    'XSkippedTaskStepStillRunning' => 'කාර්යයේ පියවරක් තවමත් ධාවනය වන නිසා {$count} ක් මඟ හැරුණි.',
    'QueueTaskDeletedPermanentlyWarning' => 'කාර්යය ස්ථිරවම ඉවත් කරනු ලැබේ. මෙය පසුගමනය කළ නොහැක.',
    'QueueTasksDeletedPermanentlyWarning' => 'කාර්යයන් ස්ථිරවම ඉවත් කරනු ලැබේ. මෙය අහෝසි කළ නොහැක.',
    'XOfY' => '{$configured} න් {$alive}',
    'UpgradeStepUpgradingExtraDatabases' => 'ස්ථාපනය කර ඇති අමතර ඇඩෝන වල දත්ත සමුදාය උත්ශ්‍රේණි කරමින්',
    'UpgradeExtraDatabasesStarted' => 'උත්ශ්‍රේණි කළ අමතර ඇඩෝන වල දත්ත සමුදාය උත්ශ්‍රේණි කරමින්...',
    'UpgradeExtraDatabaseStatusUnavailable' => 'SimpleRisk හි මෙම අනුවාදයට කුමන අමතර ඇඩෝන සබල කර ඇත්දැයි වාර්තා කළ නොහැක, එබැවින් අමතර ඇඩෝන වල දත්ත සමුදාය පියවරක් ලෙස උත්ශ්‍රේණි කර නැත. සෑම අමතර ඇඩෝනයක්ම එය පළමු වරට භාවිත කරන විට තමන්ගේ දත්ත සමුදාය උත්ශ්‍රේණි කරයි.',
    'UpgradeExtraDatabaseStatusFailed' => 'කුමන අමතර ඇඩෝන සබල කර ඇත්දැයි කියවිය නොහැකි විය (HTTP {$code}), එබැවින් අමතර ඇඩෝන වල දත්ත සමුදාය උත්ශ්‍රේණි කර නැත.',
    'UpgradeExtraDatabaseSkipped' => '{$extra}: දත්ත සමුදා උත්ශ්‍රේණි කිරීම මඟ හැරුණි; {$reason}.',
    'UpgradeExtraDatabaseSkipNotReported' => 'එය තත්ත්ව අන්ත ලක්ෂ්‍යය මගින් වාර්තා කර නැත',
