    'UpgradeExtraDatabaseSkipNoRoute' => 'එයට දත්ත සමුදාය උත්ශ්‍රේණි කිරීමක් නැත',
    'UpgradeExtraDatabaseSkipBadRoute' => 'එහි දත්ත සමුදාය උත්ශ්‍රේණි කිරීමේ මාර්ගය භාවිතයට නුසුදුසු විය',
    'UpgradeExtraDatabaseStarted' => '{$extra}: දත්ත සමුදාය උත්ශ්‍රේණි කරමින්...',
    'UpgradeExtraDatabaseDone' => '{$extra}: දත්ත සමුදාය උත්ශ්‍රේණි කරන ලදී.',
    'UpgradeExtraDatabaseFailedLine' => '{$extra}: දත්ත සමුදා උත්ශ්‍රේණි කිරීම සම්පූර්ණ නොවීය (HTTP {$code}).',
    'UpgradeExtraDatabasesFailed' => 'යෙදුම සහ දත්ත සමුදාය උත්ශ්‍රේණි කරන ලදී, නමුත් දත්ත සමුදාය උත්ශ්‍රේණි කිරීම පහත ඒවා සඳහා සම්පූර්ණ නොවීය: {$extras}. එක් එක් අමතර එක එය භාවිතා කරන පළමු වතාවේදී තමන්ගේම දත්ත සමුදාය උත්ශ්‍රේණි කිරීම අවසන් කරයි.',
    'UpgradeWorkersRestarting' => 'උත්ශ්‍රේණි කළ දිගු පූරණය කරන පරිදි පෝලිම් සේවකයන්ට යළි ආරම්භ වන ලෙස ඉල්ලා සිටිමින්.',
    'UpdateChannelLocked' => 'යාවත්කාලීන නාලිකාව config.php හි සකසා ඇති අතර මෙහි වෙනස් කළ නොහැක.',
    'UpdateChannelInvalid' => 'යාවත්කාලීන නාලිකාව "production" හෝ "rc" විය යුතුය.',
    'UpdateChannelWriteFailed' => 'යාවත්කාලීන නාලිකාව සුරැකිය නොහැකි විය. කරුණාකර නැවත උත්සාහ කරන්න.',
    'Updates' => 'යාවත්කාලීන කිරීම්',
    'UpdateChannel' => 'යාවත්කාලීන නාලිකාව',
