    'ReleaseCandidate' => 'නිකුත් කිරීමේ අපේක්ෂක අනුවාදය (Release Candidate)',
    'UpdateChannelCustom' => 'අභිරුචි (config.php හි සකසා ඇත)',
    'UpdateChannelHint' => 'Release Candidate නාලිකාව නිවැරදි කිරීම් සහ විශේෂාංග Production වෙත පැමිණීමට පෙර ලබා දෙයි.',
    'UpdateChannelPinnedInConfig' => 'config.php හි කළමනාකරණය කෙරේ. මෙම ස්ථාපනය {$channel} වෙත ඇමිණා ඇත.',
    'UpdateChannelCustomInConfig' => 'config.php හි කළමනාකරණය කෙරේ. මෙම ස්ථාපනය මෙම යාවත්කාලීන සේවා ලිපින භාවිත කරයි:',
    'UpdateChannelCouldNotBeLoaded' => 'යාවත්කාලීන නාලිකාව පූරණය කළ නොහැකි විය. නැවත උත්සාහ කිරීමට පිටුව යළි පූරණය කරන්න.',
    'SwitchUpdateChannelTo' => 'යාවත්කාලීන නාලිකාව {$channel} වෙත මාරු කරන්නද?',
    'SwitchUpdateChannelToRcBody' => 'උත්ශ්‍රේණි කිරීම්, දිගු සහ බලපත්‍රකරණය Production වෙත පැමිණීමට පෙර නිකුත්වීම් ප්‍රකාශයට පත් කරන Release Candidate නාලිකාවෙන් පැමිණෙනු ඇත.',
    'SwitchUpdateChannelToProductionBody' => 'උත්ශ්‍රේණි කිරීම්, දිගු සහ බලපත්‍රකරණය Production නාලිකාවෙන් පැමිණෙනු ඇත.',
    'UpdateChannelNoDowngrade' => 'මෙම ස්ථාපනය Production තවම ප්‍රකාශයට පත් නොකළ නිකුත්වීමක් ධාවනය කරමින් තිබිය හැක. එය පහළ අනුවාදයකට පත් නොකෙරේ. Production මීට පසු නිකුත්වීමක් ප්‍රකාශයට පත් කරන තෙක් එය එහි වත්මන් නිකුත්වීමේම පවතී.',
    'SwitchChannel' => 'නාලිකාව මාරු කරන්න',
    'UpdateChannelSwitchedTo' => 'යාවත්කාලීන නාලිකාව දැන් {$channel} වේ.',
    'UpdateChannelAheadOfChannel' => '{$version} ධාවනය වෙමින් පවතී, එය මෙම නාලිකාව ප්‍රකාශයට පත් කර නැත. එය මීට පසු නිකුත්වීමක් ප්‍රකාශයට පත් කරන තෙක් කිසිදු උත්ශ්‍රේණි කිරීමක් ඉදිරිපත් නොකෙරේ.',
    'UpdateServiceUnreachable' => 'යාවත්කාලීන සේවාවට සම්බන්ධ වීමට නොහැකි විය, එබැවින් නවතම නිකුතුව නොදනී.',
    'RegisterToUseEasyUpgrade' => 'පහසු උත්ශ්‍රේණි කිරීමේ විශේෂාංගය භාවිතා කිරීමට හැකිවීම සඳහා කරුණාකර ලියාපදිංචි වන්න.',
    'EvidenceWasDeletedSuccessfully' => 'සාක්ෂි සාර්ථකව මකා දමන ලදී.',
    'NoteWasAddedSuccessfully' => 'සටහන සාර්ථකව එකතු කරන ලදි.',
    'NoteWasDeletedSuccessfully' => 'සටහන සාර්ථකව මකා දමන ලදී.',
    'RequiredQuestionHasNoAnswerChoices' => 'මෙම ප්‍රශ්නය අවශ්‍ය ලෙස සලකුණු කර ඇති නමුත් පිළිතුරු තෝරාගැනීමේ විකල්ප නොමැත, එබැවින් ප්‍රතිචාර දක්වන්නන්ට තෝරාගැනීමට කිසිවක් නොමැති අතර එය ඉදිරිපත් කිරීම අවහිර කළ නොහැක. අවම වශයෙන් එක් පිළිතුරු විකල්පයක් එක් කරන්න, නැතහොත් අවශ්‍ය ලෙස සලකුණු ඉවත් කරන්න.',
    'PasswordResetEmailSendFailed' => 'මුරපදය යළි පිහිටුවීමේ විද්‍යුත් තැපෑල යැවිය නොහැකි විය. විද්‍යුත් තැපැල් සැකසුම් පරීක්ෂා කිරීමට කරුණාකර ඔබගේ SimpleRisk පරිපාලක අමතන්න.',
    'PasswordResetBaseUrlMismatch' => 'මුරපදය යළි පිහිටුවීමේ ඉල්ලීම මෙම ලිපිනයෙන් සම්පූර්ණ කළ නොහැකි විය. මූලික URL සැකසුම පරීක්ෂා කිරීමට කරුණාකර ඔබගේ SimpleRisk පරිපාලක අමතන්න.',
    'UploadFileTypeDetectionUnavailable' => 'මෙම සේවාදායකයේ PHP fileinfo දිගුව ස්ථාපනය කර නොමැති නිසා ගොනු උඩුගත කළ නොහැක. fileinfo දිගුව සක්‍රීය කිරීමට ඔබේ SimpleRisk පරිපාලකගෙන් ඉල්ලා සිටින්න.',
    'BackupDownloadInvalidRequest' => 'උපස්ථ බාගත කිරීමේ ඉල්ලීම වලංගු නොවේ.',
    'BackupDownloadFileNotFound' => 'උපස්ථ ගොනුව සේවාදායකයේ සොයාගත නොහැකි විය. එය ගෙන ගොස් හෝ මකා දමා තිබිය හැකිය.',
    'DocumentRequiredFieldsMissing' => 'ලේඛන ඉල්ලීමෙහි අවශ්‍ය ක්ෂේත්‍ර නොමැත: {$fields}.',
    'DeactivationGuardFailed' => 'අක්‍රිය කිරීම ආරම්භ කළ නොහැකි විය. විස්තර සඳහා පිටු ශීර්ෂයේ ඇති ඇඟවීම බලන්න.',
    'SamlKeepRoleTeamsWhenAbsent' => 'IdP විසින් භූමිකාව හෝ කණ්ඩායම් ගුණාංගය නොයවන විට පරිශීලකයාගේ වත්මන් භූමිකාව සහ කණ්ඩායම් රඳවා ගන්න',
    'SamlKeepRoleTeamsWhenAbsentHelp' => 'ක්‍රියාවිරහිත (නිර්දේශිත): ගුණාංගය ඉවත්ව ඇති පිවිසුමක් පරිශීලකයා පෙරනිමි භූමිකාවට යළි පිහිටුවන අතර කිසිදු කණ්ඩායමක් නොමැත. ක්‍රියාත්මක: පරිශීලකයා තම වත්මන් භූමිකාව සහ කණ්ඩායම් රඳවා ගනී. මෙය සක්‍රීය කරන්නේ ප්‍රවේශය රඳවා ගත යුතු පරිශීලකයින් සඳහා ඔබේ IdP ගුණාංගය නොයවන්නේ නම් පමණි (Microsoft Entra මෙය App Role නොමැති පරිශීලකයින් සඳහා කරයි). එවිට පරිශීලකයෙකු සෑම IdP කණ්ඩායමකින්ම ඉවත් කිරීමෙන් SimpleRisk හි ඔහුගේ තත්ත්වය පහත හෙළීමක් නොවන බව සලකන්න.',
    'ImportScoringValueNotRecognizedUpdate' => 'අවදානම {$risk_id} ("{$subject}"): {$field} "{$value}" අගය හඳුනා නොගත් බැවින්, මෙම අවදානමේ ලකුණු කිරීම නොවෙනස්ව පැවතුනි.',
    'ImportScoringValueNotRecognizedNew' => 'අවදානම {$risk_id} ("{$subject}"): {$field} "{$value}" අගය හඳුනා නොගත් අතර මෙම නව අවදානමට යොදනු ලැබුවේ නැත.',
    'SelectAFileToImport' => 'ආනයනය කිරීමට ගොනුවක් තෝරන්න.',
    'PasswordResetEmailSentToUser' => 'මුරපදය යළි පිහිටුවීමේ විද්‍යුත් තැපෑලක් පරිශීලකයා වෙත යවන ලදී.',
    'UnlockAccount' => 'අගුළු හරින්න',
    'AccountUnlocked' => 'ගිණුම අගුළු හරින ලදී.',
    'AccountWasNotLocked' => 'ගිණුම අගුළු දමා නොතිබුණි.',
    'AccountLockedOutHelp' => 'අසාර්ථක පිවිසුම් උත්සාහ ඉතා වැඩි ගණනකින් පසු, නැතහොත් පරිශීලකයා මුරපදය යළි පිහිටුවා සම්පූර්ණ කරන තෙක්, මෙම ගිණුම අගුළු දමනු ලැබේ. පරිශීලකයාට නැවත පිවිසීමට ඉඩ දීමට එය අගුළු හරින්න. යමෙකු ඇතුළු වීමෙන් වැළැක්වීමට, ඒ වෙනුවට ගිණුම අක්‍රිය කරන්න. අගුළු හැරීමෙන් මෙම පිටුවේ වෙනත් කිසිවක් සුරකිනු නොලැබේ.',
    'ControlIdAsDisplayed' => 'පාලන හැඳුනුම්පත (පෙන්වා ඇති පරිදි)',
    'ControlIdNotADisplayedId' => 'පේළිය මඟ හැරුණි: "{$id}" යනු පෙන්වන පාලන ID එකක් නොවේ. පෙන්වන ID 1001 සිට ආරම්භ වේ; වත්මන් ID ලබා ගැනීමට පාලන නැවත අපනයනය කරන්න.',
    'ControlIdNotFound' => 'පේළිය මඟ හැරුණි: ID "{$id}" සහිත පාලනයක් පෙන්වා නොමැත.',
    'MappedControlFrameworksInvalid' => 'සිතියම්ගත කළ පාලන රාමු අගය [{"framework":"","reference_name":"","reference_text":"","reference_subject":""}] ආකෘතියේ වලංගු JSON නොවේ, එබැවින් එම පේළිය සඳහා එය නොසලකා හරින ලදී.',
    'ControlApplicability' => 'පාලන අදාළත්වය',
    'ControlApplicabilityInvalid' => 'පාලන අදාළත්ව අගය [{"framework":"","state":"","narrative":"","provider":"","reasons":[]}] ආකෘතියේ වලංගු JSON නොවේ, එබැවින් එම පේළිය සඳහා එය නොසලකා හරින ලදී.',
    'ControlApplicabilityUnsupported' => 'SimpleRisk හි මෙම අනුවාදය පාලන අදාළත්වයට සහාය නොදක්වයි, එබැවින් පාලන අදාළත්ව අගය නොසලකා හරින ලදී.',
    'ControlApplicabilityNoPermission' => 'ඔබගේ ගිණුමට රාමු වෙනස් කළ නොහැකි නිසා පාලන අදාළත්වය නොසලකා හරින ලදී.',
    'ControlApplicabilityFrameworkNotFound' => '"{$framework}" රාමුව සඳහා අදාළත්වය යොදා නොමැත: එවැනි රාමුවක් නොමැත.',
    'ControlApplicabilityReasonNotFound' => '"{$framework}" රාමුව සඳහා අදාළත්වය යොදා නොමැත: "{$reason}" යනු දන්නා හේතුවක් නොවේ.',
    'ControlApplicabilityNotApplied' => '"{$framework}" රාමුව සඳහා අදාළත්වය යොදා නොමැත: {$message}',
    'PreviouslyAnsweredOptionChanged' => 'කලින් පිළිතුරු දී ඇත; එතැන් සිට මෙම විකල්පය වෙනස් කර හෝ ඉවත් කර ඇත.',
    'PreviouslyAnsweredChooseAgain' => 'කලින් පිළිතුරු දී ඇත, නමුත් එතැන් සිට එම විකල්පය වෙනස් කර හෝ ඉවත් කර ඇත. කරුණාකර නැවත තෝරන්න:',
    'PendingRiskScoreCouldNotBeRendered' => 'මෙම පොරොත්තු අවදානම සඳහා ලකුණු කොටස ප්‍රදර්ශනය කළ නොහැකි විය. විස්තර සඳහා SimpleRisk ලොගය බලන්න.',
    'QuestionnaireResultNotReopenableUndecided' => 'ප්‍රශ්නාවලි ප්‍රතිඵලය අනුමත කිරීම, ප්‍රතික්ෂේප කිරීම හෝ අනුමත නොකළ ලෙස සලකුණු කිරීම සිදු කර නොමැති නිසා එය නැවත විවෘත කළ නොහැක.',
    'ControlIdLegacyDatabaseId' => 'පාලන ID (දත්ත සමුදාය ID, පැරණි අපනයනය)',
    'ControlIdLegacyColumnNotice' => 'මෙම ගොනුව පැරණි පාලන ID තීරුව භාවිත කරයි; එහි ඇත්තේ SimpleRisk පෙන්වන ID නොව අමු දත්ත සමුදාය ID ය. ID, දත්ත සමුදාය ID ලෙස ගැළපිණි. අනාගත ආනයන සඳහා පෙන්වන ID ලබා ගැනීමට ("පාලන ID (පෙන්වන පරිදි)" තීරුව) පාලන නැවත අපනයනය කරන්න.',
    'ControlIdLegacyNotFound' => 'පේළිය මඟ හැරුණි: දත්ත සමුදාය ID "{$id}" සහිත පාලනයක් නොමැත.',
    'ControlIdHeaderIsLegacy' => 'කිසිවක් ආනයනය නොකෙරිණි. "පාලන ID (පෙන්වන පරිදි)" වෙත සිතියම්ගත කළ තීරුවේ ශීර්ෂය "පාලන ID" වේ; පෙර අනුවාදයකින් අපනයනය කළ පාලන ඒවායේ දත්ත සමුදාය ID ලේබල් කරන්නේ එලෙසිනි. ඒ වෙනුවට එම තීරුව "පාලන ID (දත්ත සමුදාය ID, පැරණි අපනයනය)" වෙත සිතියම්ගත කරන්න, නැතහොත් පෙන්වන ID ලබා ගැනීමට පාලන නැවත අපනයනය කරන්න. තීරුවේ ඇත්තේ 1001 හෝ ඊට වැඩි ID නම්, එය පෙන්වන-ID තීරුවකි: එහි ශීර්ෂය "පාලන ID (පෙන්වන පරිදි)" ලෙස වෙනස් කර නැවත සිතියම්ගත කරන්න.',
    'ControlIdHeaderIsDisplayed' => 'කිසිවක් ආනයනය නොකෙරිණි. "පාලන ID (දත්ත සමුදාය ID, පැරණි අපනයනය)" වෙත සිතියම්ගත කළ තීරුවේ ශීර්ෂය "පාලන ID (පෙන්වන පරිදි)" වන බැවින් එහි ඇත්තේ පෙන්වන ID ය. ඒ වෙනුවට එම තීරුව "පාලන ID (පෙන්වන පරිදි)" වෙත සිතියම්ගත කරන්න.',
