    'LookupInUseWarningOne' => 'වාර්තා 1ක් මෙම අගය භාවිත කරයි. ඔබ එය මකා දැමුවහොත්, යමෙක් වෙනත් අගයක් තෝරන තෙක් එම වාර්තාවට අගයක් නොතිබේ. මෙය අහෝසි කළ නොහැක.',
    'LookupInUseWarningMany' => 'වාර්තා {$n}ක් මෙම අගය භාවිත කරයි. ඔබ එය මකා දැමුවහොත්, යමෙක් වෙනත් අගයක් තෝරන තෙක් එම වාර්තාවලට අගයක් නොතිබේ. මෙය අහෝසි කළ නොහැක.',
    'LookupMoveRecordOneTo' => 'වාර්තාව ගෙන යා යුතු අගය (අත්‍යවශ්‍ය නොවේ)',
    'LookupMoveRecordsTo' => 'වාර්තා {$n} ගෙන යා යුතු අගය (අත්‍යවශ්‍ය නොවේ)',
    'LookupMoveHint' => 'වාර්තා පුරවා තබා ගැනීමට අගයක් තෝරන්න. ඒවා හිස් කිරීමට එය එලෙසම තබන්න.',
