    'UpgradeExtraDownloadsFailed' => 'යෙදුම සහ දත්ත සමුදාය උත්ශ්‍රේණි කරන ලදී, නමුත් මෙම අමතර දෑ (Extras) උත්ශ්‍රේණි කර නොමැත: {$extras}. ඒවා නැවත උත්සාහ කිරීමට උත්ශ්‍රේණි කිරීම නැවත ක්‍රියාත්මක කරන්න.',
    'UpgradeExtraDatabasesAlsoFailed' => 'පහත දෑ සඳහා දත්ත සමුදාය උත්ශ්‍රේණි කිරීම ද සම්පූර්ණ නොවීය: {$extras}. එක් එක් Extra එක එය පළමු වරට භාවිත කරන විට තමන්ගේම දත්ත සමුදාය උත්ශ්‍රේණි කිරීම අවසන් කරයි.',
    'YourAnswersCouldNotBeSaved' => 'ඔබේ පිළිතුරු සුරැකීමට නොහැකි විය. කිසිවක් වෙනස් කරන ලදි නැත. කරුණාකර නැවත උත්සාහ කරන්න.',
